function buildBiofingerEventSummaryFromSample(events: BiofingerEventRow[]) {
  const summaryMap = new Map<string, BiofingerEventSummaryRow>()

  events.forEach((event) => {
    const deviceId = event.attendanceDeviceId
    const summary = summaryMap.get(deviceId) || createEmptyBiofingerEventSummary(deviceId)
    summary.totalEvents += 1
    if (event.importStatus === "pending") summary.pendingEvents += 1
    if (event.importStatus === "mapped") summary.mappedEvents += 1
    if (event.importStatus === "converted") summary.convertedEvents += 1
    if (event.importStatus === "ignored") summary.ignoredEvents += 1
    if (event.importStatus === "error") summary.errorEvents += 1
    if (event.normalizedEventType === "check_in") summary.checkInEvents += 1
    if (event.normalizedEventType === "check_out") summary.checkOutEvents += 1
    if (event.normalizedEventType === "unknown") summary.unknownEvents += 1
    if (!summary.latestEventAt || event.deviceEventAt > summary.latestEventAt) summary.latestEventAt = event.deviceEventAt
    summaryMap.set(deviceId, summary)
  })

  return Array.from(summaryMap.values())
}

function sumBiofingerEventSummaries(summaries: BiofingerEventSummaryRow[]) {
  return summaries.reduce((total, summary) => ({
    attendanceDeviceId: BIOFINGER_ALL_DEVICES,
    totalEvents: total.totalEvents + summary.totalEvents,
    pendingEvents: total.pendingEvents + summary.pendingEvents,
    mappedEvents: total.mappedEvents + summary.mappedEvents,
    convertedEvents: total.convertedEvents + summary.convertedEvents,
    ignoredEvents: total.ignoredEvents + summary.ignoredEvents,
    errorEvents: total.errorEvents + summary.errorEvents,
    checkInEvents: total.checkInEvents + summary.checkInEvents,
    checkOutEvents: total.checkOutEvents + summary.checkOutEvents,
    unknownEvents: total.unknownEvents + summary.unknownEvents,
    latestEventAt: !total.latestEventAt || summary.latestEventAt > total.latestEventAt ? summary.latestEventAt : total.latestEventAt,
  }), createEmptyBiofingerEventSummary(BIOFINGER_ALL_DEVICES))
}

function mapBiofingerEventType(value: unknown): "check_in" | "check_out" | "unknown" {
  if (value === "check_in" || value === "check_out") return value
  return "unknown"
}

function normalizeBiofingerDeviceCode(value: string) {
  return value.trim().toUpperCase().replace(/[^A-Z0-9_-]+/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "")
}

function normalizeBiofingerSerial(value: string) {
  return value.trim().toUpperCase().replace(/[^A-Z0-9_-]+/g, "")
}

function buildNextBiofingerDeviceCode(devices: BiofingerDeviceRow[] = []) {
  const maxNumber = devices.reduce((max, device) => {
    const match = /^BIO-AT301-(\d+)$/i.exec(device.deviceCode)
    return match ? Math.max(max, Number(match[1]) || 0) : max
  }, 0)

  return `BIO-AT301-${String(maxNumber + 1).padStart(3, "0")}`
}

function createEmptyBiofingerDeviceForm(devices: BiofingerDeviceRow[] = []): BiofingerDeviceFormValues {
  return {
    deviceCode: buildNextBiofingerDeviceCode(devices),
    name: "",
    serialNumber: "",
    model: "AT-301",
    ipAddress: "",
    port: "4370",
    workLocationId: "",
    status: "active",
    notes: "",
  }
}

function getBiofingerDeviceFormFromRow(device: BiofingerDeviceRow): BiofingerDeviceFormValues {
  return {
    deviceCode: device.deviceCode,
    name: device.name,
    serialNumber: device.serialNumber,
    model: device.model || "AT-301",
    ipAddress: device.ipAddress,
    port: String(device.port || 4370),
    workLocationId: device.workLocationId,
    status: device.status || "active",
    notes: device.notes,
  }
}

function validateBiofingerDeviceForm(values: BiofingerDeviceFormValues, devices: BiofingerDeviceRow[] = [], editingDeviceId = "") {
  const deviceCode = normalizeBiofingerDeviceCode(values.deviceCode)
  const serialNumber = normalizeBiofingerSerial(values.serialNumber)
  const name = values.name.trim()
  const port = Number.parseInt(values.port || "4370", 10)

  if (!deviceCode) throw new Error("Kode device wajib diisi.")
  if (!name) throw new Error("Nama display device wajib diisi.")
  if (!serialNumber) throw new Error("Serial number device wajib diisi supaya receiver ADMS bisa mengenali mesin.")
  if (!Number.isFinite(port) || port < 1 || port > 65535) throw new Error("Port device harus 1 sampai 65535.")

  const duplicateCode = devices.find((device) => device.id !== editingDeviceId && device.deviceCode.toUpperCase() === deviceCode)
  if (duplicateCode) throw new Error(`Kode device ${deviceCode} sudah dipakai oleh ${duplicateCode.name}.`)

  const duplicateSerial = devices.find((device) => device.id !== editingDeviceId && device.serialNumber.toUpperCase() === serialNumber)
  if (duplicateSerial) throw new Error(`Serial ${serialNumber} sudah terdaftar di ${duplicateSerial.name}.`)

  return { deviceCode, serialNumber, name, port }
}

function formatBiofingerConnection(device: BiofingerDeviceRow) {
  const protocol = device.protocol === "adms-cloud" ? "ADMS Cloud" : device.protocol || "zk-4370"
  const address = device.ipAddress ? `${device.ipAddress}:${device.port}` : `${BIOFINGER_ADMS_RECEIVER_HOST}:${BIOFINGER_ADMS_RECEIVER_PORT}`
  return `${protocol} / ${address}`
}

function getBiofingerDeviceConnectionState(device: BiofingerDeviceRow | null): BiofingerConnectionState {
  if (!device) return "never"
  if (device.status.trim().toLowerCase() === "inactive") return "inactive"

  const lastSeenAt = Date.parse(device.lastSeenAt || "")
  if (!Number.isFinite(lastSeenAt)) return "never"

  const ageMs = Date.now() - lastSeenAt
  if (ageMs <= BIOFINGER_ONLINE_WINDOW_MS) return "online"
  if (ageMs <= BIOFINGER_IDLE_WINDOW_MS) return "idle"
  return "offline"
}

const biofingerConnectionLabel: Record<BiofingerConnectionState, string> = {
  online: "Online",
  idle: "Idle",
  offline: "Offline",
  never: "Belum online",
  inactive: "Inactive",
}

function formatBiofingerConnectionDetail(device: BiofingerDeviceRow | null) {
  if (!device) return "Belum pilih device"
  if (!device.lastSeenAt) return "Belum pernah terlihat receiver"
  return `Last seen ${formatUserDateTime(device.lastSeenAt, "-")}`
}

function BiofingerDeviceConnectionText({ device }: { device: BiofingerDeviceRow | null }) {
  const state = getBiofingerDeviceConnectionState(device)
  return (
    <span className={clsx("biofingerDeviceConnectionText", state)} title={formatBiofingerConnectionDetail(device)}>
      {biofingerConnectionLabel[state]}
    </span>
  )
}

function compareBiofingerUserIds(a: Pick<BiofingerUserLinkRow, "externalUserId" | "externalUid">, b: Pick<BiofingerUserLinkRow, "externalUserId" | "externalUid">) {
  const aId = a.externalUserId.trim()
  const bId = b.externalUserId.trim()
  const aNumeric = /^\d+$/.test(aId)
  const bNumeric = /^\d+$/.test(bId)

  if (aNumeric && bNumeric) {
    const userIdCompare = Number(aId) - Number(bId)
    if (userIdCompare !== 0) return userIdCompare
  }

  const naturalCompare = aId.localeCompare(bId, undefined, { numeric: true, sensitivity: "base" })
  if (naturalCompare !== 0) return naturalCompare

  return Number(a.externalUid ?? Number.MAX_SAFE_INTEGER) - Number(b.externalUid ?? Number.MAX_SAFE_INTEGER)
}

function compareBiofingerLinksByLatestActivity(a: BiofingerUserLinkRow, b: BiofingerUserLinkRow) {
  const aLatest = Date.parse(a.lastSeenAt || a.lastSyncedAt || "")
  const bLatest = Date.parse(b.lastSeenAt || b.lastSyncedAt || "")
  const aHasLatest = Number.isFinite(aLatest)
  const bHasLatest = Number.isFinite(bLatest)

  if (aHasLatest && bHasLatest && aLatest !== bLatest) return bLatest - aLatest
  if (aHasLatest !== bHasLatest) return aHasLatest ? -1 : 1

  return compareBiofingerUserIds(a, b)
}

function compareBiofingerUserIdsDescending(a: BiofingerUserLinkRow, b: BiofingerUserLinkRow) {
  return compareBiofingerUserIds(b, a)
}

function sortBiofingerLinks(links: BiofingerUserLinkRow[], sortMode: BiofingerMappingSort) {
  const compare = sortMode === "latest"
    ? compareBiofingerLinksByLatestActivity
    : sortMode === "user_id_asc"
      ? compareBiofingerUserIds
      : compareBiofingerUserIdsDescending

  return [...links].sort(compare)
}

function formatBiofingerEventType(value: BiofingerEventRow["normalizedEventType"]) {
  if (value === "check_in") return "Masuk"
  if (value === "check_out") return "Pulang"
  return "Unknown"
}

function BiofingerEventText({ type }: { type: BiofingerEventRow["normalizedEventType"] }) {
  return <span className={clsx("biofingerEventText", type)}>{formatBiofingerEventType(type)}</span>
}

function BiofingerDeviceStatusText({ status }: { status: string }) {
  const normalized = status.trim().toLowerCase()
  const tone = normalized === "active" ? "active" : normalized === "maintenance" ? "maintenance" : normalized === "inactive" ? "inactive" : "neutral"
  return <span className={clsx("biofingerDeviceStatusText", tone)}>{status || "unknown"}</span>
}

function BiofingerLinkStatusText({ status }: { status: BiofingerLinkStatus }) {
  return <span className={clsx("biofingerLinkStatusText", status)}>{status}</span>
}

function BiofingerUserSyncStatusText({ summary }: { summary: BiofingerUserSyncStatusSummary }) {
  const tone = summary.status === "completed"
    ? "completed"
    : summary.status === "failed" || summary.status === "expired"
      ? "failed"
      : summary.status === "pending" || summary.status === "sent" || summary.status === "acknowledged"
        ? "pending"
        : "idle"

  return (
    <span className={clsx("biofingerUserSyncStatusText", tone)}>
      {biofingerCommandStatusLabel[summary.status]}
    </span>
  )
}

function BiofingerEmployeeMappingChip({
  row,
  disabled,
  onClick,
}: {
  row: BiofingerUserLinkRow
  disabled: boolean
  onClick: () => void
}) {
  const mapped = Boolean(row.employeeId)

  return (
    <button className={clsx("biofingerMappingChip", mapped && "mapped")} type="button" disabled={disabled} data-row-action="true" onClick={onClick}>
      <span className="biofingerMappingChipIcon">{mapped ? <UserRoundCheck size={15} /> : <UserPlus size={15} />}</span>
      <span className="biofingerMappingChipCopy">
        <strong>{mapped ? row.employeeName || "Karyawan dipilih" : "Belum mapped"}</strong>
        <small>{mapped ? row.employeeCode || "Mapped manual" : `Klik untuk mapping User ID ${row.externalUserId}`}</small>
      </span>
    </button>
  )
}

function getPlainRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {}
}

function getBiofingerCommandTimestamp(command: Pick<BiofingerDeviceCommandRow, "respondedAt" | "sentAt" | "requestedAt" | "expiresAt">) {
  const timestamps = [command.respondedAt, command.sentAt, command.requestedAt, command.expiresAt]
    .map((value) => Date.parse(value || ""))
    .filter(Number.isFinite)
  return timestamps.length ? Math.max(...timestamps) : 0
}

function mapBiofingerDeviceCommandRecord(row: Record<string, unknown>): BiofingerDeviceCommandRow {
  return {
    id: String(row.id || ""),
    attendanceDeviceId: String(row.attendance_device_id || ""),
    requestNo: row.request_no === null || row.request_no === undefined ? null : Number(row.request_no),
    commandType: String(row.command_type || "sync_users"),
    status: mapBiofingerCommandStatus(row.status),
    attempts: Number(row.attempts || 0),
    maxAttempts: Number(row.max_attempts || 3),
    responseCode: row.response_code === null || row.response_code === undefined ? null : Number(row.response_code),
    lastError: String(row.last_error || ""),
    requestedAt: String(row.requested_at || ""),
    sentAt: String(row.sent_at || ""),
    respondedAt: String(row.responded_at || ""),
    expiresAt: String(row.expires_at || ""),
  }
}

function getBiofingerMetadataUserSyncStatus(device: BiofingerDeviceRow): BiofingerUserSyncStatusSummary | null {
  const request = getPlainRecord(device.metadata.biofinger_user_sync_request)
  if (!Object.keys(request).length) return null

  const status = mapBiofingerCommandStatus(request.status)
  const updatedAt = String(request.completed_at || request.responded_at || request.sent_at || request.requested_at || "")
  return {
    status,
    detail: String(request.last_error || biofingerCommandStatusMeta[status]),
    updatedAt,
    lastError: String(request.last_error || ""),
    source: "metadata",
  }
}

function getLatestBiofingerUserSyncStatus(
  devices: BiofingerDeviceRow[],
  commands: BiofingerDeviceCommandRow[],
): BiofingerUserSyncStatusSummary {
  const latestCommand = commands
    .filter((command) => command.commandType === "sync_users")
    .sort((a, b) => getBiofingerCommandTimestamp(b) - getBiofingerCommandTimestamp(a))[0]

  if (latestCommand) {
    return {
      status: latestCommand.status,
      detail: latestCommand.lastError || biofingerCommandStatusMeta[latestCommand.status],
      updatedAt: latestCommand.respondedAt || latestCommand.sentAt || latestCommand.requestedAt,
      lastError: latestCommand.lastError,
      source: "queue",
    }
  }

  const metadataStatus = devices
    .map(getBiofingerMetadataUserSyncStatus)
    .filter((status): status is BiofingerUserSyncStatusSummary => Boolean(status))
    .sort((a, b) => (Date.parse(b.updatedAt || "") || 0) - (Date.parse(a.updatedAt || "") || 0))[0]

  return metadataStatus || {
    status: "idle",
    detail: biofingerCommandStatusMeta.idle,
    updatedAt: "",
    lastError: "",
    source: "none",
  }
}

function mapBiofingerDeviceRecord(row: Record<string, unknown>, workLocationMap: Map<string, BiofingerWorkLocationOption>): BiofingerDeviceRow {
  return {
    workLocationId: String(row.work_location_id || ""),
    workLocationName: workLocationMap.get(String(row.work_location_id || ""))?.name || "",
    id: String(row.id || ""),
    deviceCode: String(row.device_code || ""),
    name: String(row.name || row.device_code || "Biofinger"),
    vendor: String(row.vendor || "Biofinger"),
    model: String(row.model || ""),
    serialNumber: String(row.serial_number || ""),
    macAddress: String(row.mac_address || ""),
    ipAddress: String(row.ip_address || ""),
    port: Number(row.port || 4370),
    protocol: String(row.protocol || "zk-4370"),
    status: String(row.status || "active"),
    lastSeenAt: String(row.last_seen_at || ""),
    lastSyncAt: String(row.last_sync_at || ""),
    syncCursorAt: String(row.sync_cursor_at || ""),
    metadata: getPlainRecord(row.metadata),
    notes: String(row.notes || ""),
  }
}

async function loadBiofingerData(): Promise<BiofingerData> {
  const devicesQuery = supabase
    .from("attendance_devices")
    .select("id, device_code, name, vendor, model, serial_number, mac_address, ip_address, port, protocol, work_location_id, status, last_seen_at, last_sync_at, sync_cursor_at, metadata, notes")
    .order("name", { ascending: true })
  const linksQuery = supabase
    .from("employee_attendance_device_links")
    .select("id, employee_id, attendance_device_id, external_user_id, external_uid, external_name, privilege, status, matched_by, last_seen_at, last_synced_at, notes")
    .order("external_user_id", { ascending: true })
  const eventsQuery = supabase
    .from("biofinger_attendance_events")
    .select("id, attendance_device_id, external_user_id, employee_id, device_event_at, attendance_date, punch, status_code, normalized_event_type, import_status, source_hash", { count: "planned" })
    .order("device_event_at", { ascending: false })
    .limit(200)
  const eventSummaryQuery = supabase.rpc("get_biofinger_attendance_event_summary")
  const commandsQuery = supabase
    .from("biofinger_device_commands")
    .select("id, attendance_device_id, request_no, command_type, status, attempts, max_attempts, response_code, last_error, requested_at, sent_at, responded_at, expires_at")
    .order("requested_at", { ascending: false })
    .limit(100)
  const employeesQuery = supabase
    .from("employees")
    .select("id, employee_code, full_name, status")
    .is("deleted_at", null)
    .order("employee_code", { ascending: true })
  const workLocationsQuery = supabase
    .from("work_locations")
    .select("id, code, name, is_active")
    .order("sort_order", { ascending: true })
    .order("code", { ascending: true })

  const [devicesResult, linksResult, employeesResult, workLocationsResult, eventsResult, eventSummaryResult, commandsResult] = await Promise.all([
    devicesQuery,
    linksQuery,
    employeesQuery,
    workLocationsQuery,
    eventsQuery,
    eventSummaryQuery,
    commandsQuery,
  ])

  const biofingerSchemaError = devicesResult.error || linksResult.error
  if (biofingerSchemaError) {
    if (isMissingBiofingerSchema(biofingerSchemaError)) {
      return { schemaReady: false, devices: [], links: [], events: [], eventCount: 0, eventSummary: [], commands: [], employees: [], workLocations: [] }
    }
    throw biofingerSchemaError
  }
  if (eventsResult.error && isMissingBiofingerSchema(eventsResult.error)) {
    return { schemaReady: false, devices: [], links: [], events: [], eventCount: 0, eventSummary: [], commands: [], employees: [], workLocations: [] }
  }
  if (employeesResult.error) throw employeesResult.error
  if (workLocationsResult.error) throw workLocationsResult.error

  const employees = (employeesResult.data || []).map((row: Record<string, unknown>) => ({
    id: String(row.id || ""),
    employeeCode: String(row.employee_code || ""),
    fullName: String(row.full_name || ""),
    status: mapEmployeeStatus(row.status),
  }))
  const employeeMap = new Map(employees.map((employee) => [employee.id, employee]))
  const workLocations = (workLocationsResult.data || []).map((row: Record<string, unknown>) => ({
    id: String(row.id || ""),
    code: String(row.code || ""),
    name: String(row.name || ""),
    isActive: row.is_active !== false,
  }))
  const workLocationMap = new Map(workLocations.map((location) => [location.id, location]))

  const devices = (devicesResult.data || []).map((row: Record<string, unknown>) => mapBiofingerDeviceRecord(row, workLocationMap))
  const commandLoadError = commandsResult.error && !isMissingBiofingerCommandSchema(commandsResult.error)
    ? getFriendlySupabaseError(commandsResult.error, "Status command Biofinger belum bisa dimuat.")
    : ""
  const commands = commandsResult.error ? [] : (commandsResult.data || []).map((row: Record<string, unknown>) => mapBiofingerDeviceCommandRecord(row))

  const links = (linksResult.data || []).map((row: Record<string, unknown>) => {
    const employeeId = row.employee_id ? String(row.employee_id) : ""
    const employee = employeeMap.get(employeeId)

    return {
      id: String(row.id || ""),
      attendanceDeviceId: String(row.attendance_device_id || ""),
      employeeId,
      employeeCode: employee?.employeeCode || "",
      employeeName: employee?.fullName || "",
      externalUserId: String(row.external_user_id || ""),
      externalUid: row.external_uid === null || row.external_uid === undefined ? null : Number(row.external_uid),
      externalName: String(row.external_name || ""),
      privilege: row.privilege === null || row.privilege === undefined ? null : Number(row.privilege),
      status: mapBiofingerLinkStatus(row.status),
      matchedBy: String(row.matched_by || "manual"),
      lastSeenAt: String(row.last_seen_at || ""),
      lastSyncedAt: String(row.last_synced_at || ""),
      notes: String(row.notes || ""),
    }
  }).sort(compareBiofingerLinksByLatestActivity)

  const eventLoadError = eventsResult.error ? getFriendlySupabaseError(eventsResult.error, "Raw event Biofinger belum bisa dimuat.") : ""
  const events = eventsResult.error ? [] : (eventsResult.data || []).map((row: Record<string, unknown>) => {
    const employeeId = row.employee_id ? String(row.employee_id) : ""
    const employee = employeeMap.get(employeeId)

    return {
      id: String(row.id || ""),
      attendanceDeviceId: String(row.attendance_device_id || ""),
      externalUserId: String(row.external_user_id || ""),
      employeeId,
      employeeCode: employee?.employeeCode || "",
      employeeName: employee?.fullName || "",
      deviceEventAt: String(row.device_event_at || ""),
      attendanceDate: String(row.attendance_date || ""),
      punch: row.punch === null || row.punch === undefined ? null : Number(row.punch),
      statusCode: row.status_code === null || row.status_code === undefined ? null : Number(row.status_code),
      normalizedEventType: mapBiofingerEventType(row.normalized_event_type),
      importStatus: mapBiofingerImportStatus(row.import_status),
      sourceHash: String(row.source_hash || ""),
    }
  })
  const eventSummaryIsFallback = Boolean(eventSummaryResult.error)
  const eventSummaryLoadError = eventSummaryResult.error
    ? isMissingBiofingerSchema(eventSummaryResult.error)
      ? "Migration ringkasan event belum aktif di database; angka memakai sample terakhir."
      : getFriendlySupabaseError(eventSummaryResult.error, "Ringkasan raw event Biofinger belum bisa dimuat.")
    : ""
  const eventSummary = eventSummaryResult.error
    ? buildBiofingerEventSummaryFromSample(events)
    : ((eventSummaryResult.data || []) as Array<Record<string, unknown>>).map((row) => mapBiofingerEventSummary(row))
  const totalEventSummary = sumBiofingerEventSummaries(eventSummary)
  const eventCount = totalEventSummary.totalEvents || eventsResult.count || events.length

  return {
    schemaReady: true,
    devices,
    links,
    events,
    eventCount,
    eventLoadError,
    eventSummary,
    eventSummaryLoadError,
    eventSummaryIsFallback,
    commands,
    commandLoadError,
    employees,
    workLocations,
  }
}

async function updateBiofingerUserLink(row: BiofingerUserLinkRow, employeeId: string, status?: BiofingerLinkStatus) {
  const nextStatus = status || (employeeId ? "active" : "pending")
  if (nextStatus === "active" && !employeeId) {
    throw new Error("Pilih karyawan DMS sebelum mengaktifkan mapping Biofinger.")
  }

  const mappingResult = await supabase.rpc("update_biofinger_user_mapping", {
    target_link_id: row.id,
    target_employee_id: employeeId || null,
    target_status: nextStatus,
  })

  if (!mappingResult.error) return
  if (!isMissingBiofingerMappingRpc(mappingResult.error)) throw mappingResult.error

  const updatedAt = new Date().toISOString()
  const { error } = await supabase
    .from("employee_attendance_device_links")
    .update({
      employee_id: employeeId || null,
      status: nextStatus,
      matched_by: "manual",
      last_synced_at: updatedAt,
      updated_at: updatedAt,
    })
    .eq("id", row.id)

  if (error) throw error

  const eventPayload = nextStatus === "active"
    ? { employee_id: employeeId, import_status: "mapped", updated_at: updatedAt }
    : { employee_id: null, import_status: nextStatus === "ignored" ? "ignored" : "pending", updated_at: updatedAt }

  const eventUpdate = await supabase
    .from("biofinger_attendance_events")
    .update(eventPayload)
    .eq("attendance_device_id", row.attendanceDeviceId)
    .eq("external_user_id", row.externalUserId)
    .in("import_status", ["pending", "mapped", "ignored"])

  if (eventUpdate.error) throw eventUpdate.error

  await writeAuditLog("Update Biofinger mapping", "employee_attendance_device_links", row.id, {
    module: "biofinger",
    source: "frontend-fallback",
    attendance_device_id: row.attendanceDeviceId,
    external_user_id: row.externalUserId,
    previous_status: row.status,
    next_status: nextStatus,
    previous_employee_id: row.employeeId || null,
    next_employee_id: employeeId || null,
    events_updated: eventUpdate.count ?? null,
  }).catch(() => undefined)
}

async function convertBiofingerAttendanceEvents(deviceId: string, limit = 1000) {
  const { data, error } = await supabase.rpc("convert_biofinger_attendance_events", {
    target_device_id: deviceId && deviceId !== BIOFINGER_ALL_DEVICES ? deviceId : null,
    target_limit: limit,
  })

  if (error) throw error
  const row = Array.isArray(data) ? data[0] as Record<string, unknown> | undefined : data as Record<string, unknown> | null
  return mapBiofingerConversionSummary(row)
}

function isMissingBiofingerUserSyncRpc(error: unknown) {
  if (!error || typeof error !== "object") return false
  const record = error as { code?: string; message?: string }
  const message = String(record.message || "").toLowerCase()
  return record.code === "PGRST202"
    || record.code === "42883"
    || message.includes("request_biofinger_user_sync")
    || message.includes("could not find the function")
}

async function requestBiofingerUserSyncFallback(devices: BiofingerDeviceRow[]) {
  const eligibleDevices = devices.filter((device) => device.id && ["active", "maintenance"].includes(device.status.toLowerCase()))
  if (!eligibleDevices.length) {
    throw new Error("Tidak ada device Biofinger aktif untuk diminta sync user.")
  }

  const requestedAt = new Date().toISOString()
  const requestNonce = typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${Date.now()}`

  await Promise.all(eligibleDevices.map((device) => {
    const metadata = {
      ...device.metadata,
      biofinger_user_sync_request: {
        status: "pending",
        pin: "ALL",
        source: "dms-ui-metadata-fallback",
        requested_at: requestedAt,
        nonce: requestNonce,
      },
    }

    return supabase
      .from("attendance_devices")
      .update({ metadata, updated_at: requestedAt })
      .eq("id", device.id)
      .then(({ error }) => {
        if (error) throw error
      })
  }))

  return {
    commandsCreated: eligibleDevices.length,
    commandsSkipped: 0,
    fallback: true,
  }
}

async function requestBiofingerUserSync(deviceId: string, devices: BiofingerDeviceRow[]) {
  const targetDeviceId = deviceId && deviceId !== BIOFINGER_ALL_DEVICES ? deviceId : null
  const targetDevices = targetDeviceId ? devices.filter((device) => device.id === targetDeviceId) : devices
  const { data, error } = await supabase.rpc("request_biofinger_user_sync", {
    target_device_id: targetDeviceId,
    target_pin: null,
  })

  if (!error) {
    const row = getPlainRecord(data)
    return {
      commandsCreated: Number(row.commands_created || 0),
      commandsSkipped: Number(row.commands_skipped || 0),
      fallback: false,
    }
  }

  if (isMissingBiofingerUserSyncRpc(error)) {
    return requestBiofingerUserSyncFallback(targetDevices)
  }

  throw error
}

async function createBiofingerDeviceRegistry(values: BiofingerDeviceFormValues, devices: BiofingerDeviceRow[] = []) {
  const { deviceCode, serialNumber, name, port } = validateBiofingerDeviceForm(values, devices)

  const { data, error } = await supabase
    .from("attendance_devices")
    .insert({
      device_code: deviceCode,
      name,
      vendor: "Biofinger",
      model: values.model.trim() || "AT-301",
      serial_number: serialNumber,
      ip_address: values.ipAddress.trim() || null,
      port,
      protocol: "adms-cloud",
      work_location_id: values.workLocationId || null,
      status: values.status || "active",
      metadata: {
        source: "management-app",
        registration_mode: "adms-cloud",
        receiver_host: BIOFINGER_ADMS_RECEIVER_HOST,
        receiver_port: BIOFINGER_ADMS_RECEIVER_PORT,
        allowlist_source: "device-registry",
      },
      notes: values.notes.trim() || "Ditambahkan dari Biofinger Device Registry.",
    })
    .select("id, device_code, name, vendor, model, serial_number, mac_address, ip_address, port, protocol, work_location_id, status, last_seen_at, last_sync_at, sync_cursor_at, notes")
    .single()

  if (error) throw error
  return data as Record<string, unknown>
}

async function updateBiofingerDeviceRegistry(deviceId: string, values: BiofingerDeviceFormValues, devices: BiofingerDeviceRow[] = []) {
  const { deviceCode, serialNumber, name, port } = validateBiofingerDeviceForm(values, devices, deviceId)

  const { error } = await supabase
    .from("attendance_devices")
    .update({
      device_code: deviceCode,
      name,
      model: values.model.trim() || "AT-301",
      serial_number: serialNumber,
      ip_address: values.ipAddress.trim() || null,
      port,
      protocol: "adms-cloud",
      work_location_id: values.workLocationId || null,
      status: values.status || "active",
      notes: values.notes.trim() || null,
      updated_at: new Date().toISOString(),
    })
    .eq("id", deviceId)

  if (error) throw error
}

function mapEmployeeRow(
  row: Record<string, unknown>,
  divisionMap: Map<string, EmployeeOption>,
  positionMap: Map<string, EmployeeOption>,
  locationMap: Map<string, EmployeeOption>,
  shiftMap: Map<string, EmployeeOption>,
  policyMap = new Map<string, AttendancePolicyOption>(),
  faceProfileMap = new Map<string, Record<string, unknown>>(),
  faceUrlMap = new Map<string, string>(),
  biofingerLinkMap = new Map<string, EmployeeBiofingerLink[]>(),
  employmentTypeMap = new Map<string, EmploymentTypeOption>(),
): EmployeeDirectoryRow {
  const divisionId = row.division_id ? String(row.division_id) : ""
  const positionId = row.position_id ? String(row.position_id) : ""
  const workLocationId = row.work_location_id ? String(row.work_location_id) : ""
  const shiftId = row.shift_id ? String(row.shift_id) : ""
  const attendancePolicyId = row.attendance_policy_id ? String(row.attendance_policy_id) : ""
  const employmentTypeId = row.employment_type_id ? String(row.employment_type_id) : ""
  const employmentType = employmentTypeMap.get(employmentTypeId)
  const faceProfile = faceProfileMap.get(String(row.id))
  const referenceImagePath = String(faceProfile?.reference_image_path || "")

  return {
    id: String(row.id),
    employeeCode: String(row.employee_code || ""),
    fullName: String(row.full_name || ""),
    photoPath: String(row.photo_path || ""),
    photoUrl: getEmployeePhotoPublicUrl(String(row.photo_path || "")),
    nik: String(row.nik || ""),
    phone: String(row.phone || ""),
    email: String(row.email || ""),
    divisionId,
    divisionName: divisionMap.get(divisionId)?.name || "Belum pilih divisi",
    positionId,
    positionName: positionMap.get(positionId)?.name || "Belum pilih jabatan",
    workLocationId,
    workLocationName: locationMap.get(workLocationId)?.name || "Belum pilih lokasi",
    shiftId,
    shiftName: shiftMap.get(shiftId)?.name || "Belum pilih shift",
    salaryType: mapEmployeeSalaryType(row.salary_type),
    dailySalary: Number(row.daily_salary || 0),
    monthlySalary: Number(row.monthly_salary || 0),
    payrollMethod: mapEmployeePayrollMethod(row.payroll_method),
    prorateEnabled: row.prorate_enabled !== false,
    employmentTypeId,
    employmentTypeCode: employmentType?.code || "",
    employmentTypeName: employmentType?.name || "Karyawan Tetap",
    payrollEligible: row.payroll_eligible !== false,
    employeePayPolicy: mapEmployeePayPolicy(row.employee_pay_policy),
    allowanceAmount: Number(row.allowance_amount || 0),
    attendanceRequired: row.attendance_required !== false,
    qrToken: String(row.qr_token || ""),
    rfidUid: String(row.rfid_uid || ""),
    attendancePolicyId,
    attendancePolicyName: policyMap.get(attendancePolicyId)?.name || "Multi Method",
    kioskAccessEnabled: row.kiosk_access_enabled !== false,
    lastCardIssuedAt: row.last_card_issued_at ? String(row.last_card_issued_at) : "",
    joinDate: row.join_date ? String(row.join_date) : "",
    payrollCycleDays: Number(row.payroll_cycle_days || 0),
    payrollCycleOpeningDate: row.payroll_cycle_opening_date ? String(row.payroll_cycle_opening_date) : "",
    status: mapEmployeeStatus(row.status),
    faceProfileId: String(faceProfile?.id || ""),
    faceProfileStatus: mapEmployeeFaceProfileStatus(faceProfile?.status),
    faceProfileThreshold: Number(faceProfile?.face_score_threshold || 85),
    faceProfileRequired: faceProfile?.verification_required !== false,
    faceReferenceImagePath: referenceImagePath,
    faceReferenceImageUrl: referenceImagePath ? faceUrlMap.get(referenceImagePath) || "" : "",
    faceProfileSubmittedAt: String(faceProfile?.submitted_at || ""),
    faceProfileReviewedAt: String(faceProfile?.reviewed_at || ""),
    faceProfileReviewNotes: String(faceProfile?.review_notes || ""),
    biofingerLinks: biofingerLinkMap.get(String(row.id)) || [],
    notes: String(row.notes || ""),
    deletedAt: row.deleted_at ? String(row.deleted_at) : "",
  }
}

async function loadEmployeeData(): Promise<EmployeeDirectoryData> {
  const legacyEmployeeSelect = "id, employee_code, full_name, photo_path, nik, phone, email, division_id, position_id, work_location_id, shift_id, salary_type, daily_salary, monthly_salary, payroll_method, prorate_enabled, join_date, payroll_cycle_days, status, notes, deleted_at, created_at"
  const baseEmployeeSelect = `${legacyEmployeeSelect}, payroll_cycle_opening_date`
  const employmentEmployeeSelect = `${baseEmployeeSelect}, employment_type_id, payroll_eligible, employee_pay_policy, allowance_amount, attendance_required`
  const legacyKioskEmployeeSelect = `${legacyEmployeeSelect}, qr_token, rfid_uid, attendance_policy_id, kiosk_access_enabled, last_card_issued_at`
  const kioskEmployeeSelect = `${baseEmployeeSelect}, qr_token, rfid_uid, attendance_policy_id, kiosk_access_enabled, last_card_issued_at`
  const employmentKioskEmployeeSelect = `${employmentEmployeeSelect}, qr_token, rfid_uid, attendance_policy_id, kiosk_access_enabled, last_card_issued_at`
  const employeeQuery = supabase.from("employees").select(employmentKioskEmployeeSelect).order("employee_code", { ascending: true })
  const [initialEmployeesResult, divisions, positions, locations, shifts, employmentTypesResult, faceProfiles, policies, biofingerLinksResult, biofingerDevicesResult] = await Promise.all([
    employeeQuery,
    supabase.from("divisions").select("id, code, name, is_active, sort_order").order("sort_order", { ascending: true }).order("code", { ascending: true }),
    supabase.from("positions").select("id, code, name, division_id, is_active, sort_order").order("sort_order", { ascending: true }).order("code", { ascending: true }),
    supabase.from("work_locations").select("id, code, name, is_active, sort_order").order("sort_order", { ascending: true }).order("code", { ascending: true }),
    supabase.from("shifts").select("id, code, name, is_active, sort_order").order("sort_order", { ascending: true }).order("code", { ascending: true }),
    supabase.from("employee_employment_types").select("id, code, name, description, payroll_eligible_default, default_pay_policy, allowance_amount, requires_attendance, is_active, sort_order").order("sort_order", { ascending: true }).order("code", { ascending: true }),
    supabase.from("employee_face_profiles").select("id, employee_id, status, verification_required, face_score_threshold, reference_image_path, submitted_at, reviewed_at, review_notes"),
    supabase.from("attendance_policies").select("id, code, name, allowed_media, require_face, require_location, status").order("code", { ascending: true }),
    supabase.from("employee_attendance_device_links").select("id, employee_id, attendance_device_id, external_user_id, external_uid, external_name, status, matched_by, last_seen_at, last_synced_at"),
    supabase.from("attendance_devices").select("id, device_code, name, serial_number"),
  ])
  let kioskSchemaReady = true
  let payrollOpeningSchemaReady = true
  let employmentSchemaReady = true
  let employeesResult = initialEmployeesResult as {
    data: Array<Record<string, unknown>> | null
    error: unknown | null
  }

  if (initialEmployeesResult.error) {
    if (isMissingEmploymentTypeSchema(initialEmployeesResult.error)) {
      employmentSchemaReady = false
      employeesResult = await supabase.from("employees").select(kioskEmployeeSelect).order("employee_code", { ascending: true })
      if (employeesResult.error && isMissingKioskEmployeeSchema(employeesResult.error)) {
        kioskSchemaReady = false
        employeesResult = await supabase.from("employees").select(baseEmployeeSelect).order("employee_code", { ascending: true })
      }
    } else if (isMissingPayrollOpeningSchema(initialEmployeesResult.error)) {
      payrollOpeningSchemaReady = false
      employeesResult = await supabase.from("employees").select(legacyKioskEmployeeSelect).order("employee_code", { ascending: true })

      if (employeesResult.error && isMissingKioskEmployeeSchema(employeesResult.error)) {
        kioskSchemaReady = false
        employeesResult = await supabase.from("employees").select(legacyEmployeeSelect).order("employee_code", { ascending: true })
      }
    } else if (isMissingKioskEmployeeSchema(initialEmployeesResult.error)) {
      kioskSchemaReady = false
      employeesResult = await supabase.from("employees").select(baseEmployeeSelect).order("employee_code", { ascending: true })

      if (employeesResult.error && isMissingPayrollOpeningSchema(employeesResult.error)) {
        payrollOpeningSchemaReady = false
        employeesResult = await supabase.from("employees").select(legacyEmployeeSelect).order("employee_code", { ascending: true })
      }
    }
  }
  const employmentTypeError = employmentTypesResult.error && !isMissingEmploymentTypeSchema(employmentTypesResult.error) ? employmentTypesResult.error : null
  const error = employeesResult.error || divisions.error || positions.error || locations.error || shifts.error || employmentTypeError || faceProfiles.error

  if (error) throw error

  const divisionOptions = (divisions.data || []).map((row) => ({
    id: String(row.id),
    code: String(row.code || ""),
    name: String(row.name || ""),
    isActive: row.is_active !== false,
  }))
  const positionOptions = (positions.data || []).map((row) => ({
    id: String(row.id),
    code: String(row.code || ""),
    name: String(row.name || ""),
    divisionId: row.division_id ? String(row.division_id) : "",
    isActive: row.is_active !== false,
  }))
  const locationOptions = (locations.data || []).map((row) => ({
    id: String(row.id),
    code: String(row.code || ""),
    name: String(row.name || ""),
    isActive: row.is_active !== false,
  }))
  const employmentTypes = employmentTypesResult.error ? [] : (employmentTypesResult.data || []).map((row) => ({
    id: String(row.id),
    code: String(row.code || ""),
    name: String(row.name || ""),
    description: String(row.description || ""),
    payrollEligibleDefault: row.payroll_eligible_default !== false,
    defaultPayPolicy: mapEmployeePayPolicy(row.default_pay_policy),
    allowanceAmount: Number(row.allowance_amount || 0),
    requiresAttendance: row.requires_attendance !== false,
    isActive: row.is_active !== false,
  }))
  const shiftOptions = (shifts.data || []).map((row) => ({
    id: String(row.id),
    code: String(row.code || ""),
    name: String(row.name || ""),
    isActive: row.is_active !== false,
  }))
  const policyOptions = policies.error ? [] : (policies.data || []).map((row) => ({
    id: String(row.id),
    code: String(row.code || ""),
    name: String(row.name || ""),
    allowedMedia: Array.isArray(row.allowed_media) ? row.allowed_media.map((item) => String(item)) : [],
    requireFace: row.require_face === true,
    requireLocation: row.require_location !== false,
    isActive: row.status !== "inactive",
  }))
  const divisionMap = new Map(divisionOptions.map((item) => [item.id, item]))
  const positionMap = new Map(positionOptions.map((item) => [item.id, item]))
  const locationMap = new Map(locationOptions.map((item) => [item.id, item]))
  const shiftMap = new Map(shiftOptions.map((item) => [item.id, item]))
  const employmentTypeMap = new Map(employmentTypes.map((item) => [item.id, item]))
  const policyMap = new Map(policyOptions.map((item) => [item.id, item]))
  const faceProfileMap = new Map(((faceProfiles.data || []) as Array<Record<string, unknown>>).map((row) => [String(row.employee_id || ""), row]))
  const faceReferencePaths = Array.from(new Set(((faceProfiles.data || []) as Array<Record<string, unknown>>).map((row) => String(row.reference_image_path || "")).filter(Boolean)))
  const faceUrlEntries = await Promise.all(faceReferencePaths.map(async (path) => [path, await getEmployeeFaceSignedUrl(path)] as const))
  const faceUrlMap = new Map(faceUrlEntries)
  const biofingerDeviceMap = new Map(((biofingerDevicesResult.error ? [] : biofingerDevicesResult.data || []) as Array<Record<string, unknown>>).map((row) => [String(row.id || ""), row]))
  const biofingerLinkMap = new Map<string, EmployeeBiofingerLink[]>()

  ;((biofingerLinksResult.error ? [] : biofingerLinksResult.data || []) as Array<Record<string, unknown>>).forEach((row) => {
    const employeeId = String(row.employee_id || "")
    if (!employeeId) return

    const attendanceDeviceId = String(row.attendance_device_id || "")
    const device = biofingerDeviceMap.get(attendanceDeviceId)
    const link: EmployeeBiofingerLink = {
      id: String(row.id || ""),
      attendanceDeviceId,
      deviceCode: String(device?.device_code || ""),
      deviceName: String(device?.name || "Biofinger"),
      deviceSerialNumber: String(device?.serial_number || ""),
      externalUserId: String(row.external_user_id || ""),
      externalUid: row.external_uid === null || row.external_uid === undefined ? null : Number(row.external_uid),
      externalName: String(row.external_name || ""),
      status: mapBiofingerLinkStatus(row.status),
      matchedBy: String(row.matched_by || ""),
      lastSeenAt: String(row.last_seen_at || ""),
      lastSyncedAt: String(row.last_synced_at || ""),
    }
    biofingerLinkMap.set(employeeId, [...(biofingerLinkMap.get(employeeId) || []), link])
  })

  return {
    rows: (employeesResult.data || []).map((row) => mapEmployeeRow(row, divisionMap, positionMap, locationMap, shiftMap, policyMap, faceProfileMap, faceUrlMap, biofingerLinkMap, employmentTypeMap)),
    divisions: divisionOptions,
    positions: positionOptions,
    locations: locationOptions,
    shifts: shiftOptions,
    employmentTypes,
    policies: policyOptions,
    kioskSchemaReady,
    payrollOpeningSchemaReady,
  }
}

function mapShiftScheduleStatus(value: unknown): ShiftScheduleStatus {
  return value === "cancelled" ? "cancelled" : "active"
}

function createShiftScheduleOption(row: Record<string, unknown>): ShiftScheduleShiftOption {
  return {
    id: String(row.id || ""),
    code: String(row.code || ""),
    name: String(row.name || ""),
    isActive: row.is_active !== false,
    startTime: String(row.start_time || ""),
    endTime: String(row.end_time || ""),
    lateToleranceMinutes: Number(row.late_tolerance_minutes || 0),
    earlyLeaveToleranceMinutes: Number(row.early_leave_tolerance_minutes || 0),
  }
}

function getShiftScheduleTimeLabel(shift?: Pick<ShiftScheduleShiftOption, "startTime" | "endTime"> | null) {
  if (!shift?.startTime || !shift?.endTime) return "Jam belum lengkap"
  return `${formatShiftClock(shift.startTime)} - ${formatShiftClock(shift.endTime)}`
}

function getShiftScheduleDisplayShiftName(name?: string | null, fallback = "Belum pilih shift") {
  const cleanName = String(name || "").trim()
  if (!cleanName) return fallback

  const normalizedName = cleanName.replace(/\s+/g, "").toUpperCase()
  return normalizedName === "JAMNORMAL" ? "Default" : cleanName
}

function getShiftScheduleSourceLabel(row: ShiftScheduleRow) {
  if (row.scheduleId && row.scheduleStatus === "cancelled") return "Jadwal dibatalkan"
  if (row.source === "daily_schedule") return "Jadwal harian"
  if (row.source === "no_shift") return "Belum ada shift"
  return "Default karyawan"
}

function getShiftScheduleStatusLabel(row: ShiftScheduleRow) {
  if (row.scheduleId && row.scheduleStatus === "cancelled") return "Dibatalkan"
  if (row.source === "daily_schedule") return "Terjadwal"
  if (row.source === "no_shift") return "Belum siap"
  return "Fallback"
}

function getShiftScheduleResolvedShiftName(row: ShiftScheduleRow) {
  return getShiftScheduleDisplayShiftName(row.source === "daily_schedule" ? row.scheduleShiftName : row.defaultShiftName)
}

function getShiftScheduleResolvedLocationName(row: ShiftScheduleRow) {
  return row.source === "daily_schedule" ? row.scheduleWorkLocationName || row.defaultWorkLocationName : row.defaultWorkLocationName
}

const SHIFT_SCHEDULE_DAY_LABELS = ["Min", "Sen", "Sel", "Rab", "Kam", "Jum", "Sab"]

function getShiftScheduleMonthValue(dateKey = getLocalDateKey()) {
  return /^\d{4}-\d{2}-\d{2}$/.test(dateKey) ? dateKey.slice(0, 7) : getLocalDateKey().slice(0, 7)
}

function getShiftScheduleMonthDate(dateKey: string) {
  const [year, month, day] = dateKey.split("-").map(Number)
  if (!year || !month || !day) return null
  const parsedDate = new Date(year, month - 1, day)
  if (parsedDate.getFullYear() !== year || parsedDate.getMonth() !== month - 1 || parsedDate.getDate() !== day) return null
  return parsedDate
}

function getShiftScheduleMonthDates(monthValue: string) {
  const [year, month] = monthValue.split("-").map(Number)
  if (!year || !month || month < 1 || month > 12) return getShiftScheduleMonthDates(getLocalDateKey().slice(0, 7))

  const totalDays = new Date(year, month, 0).getDate()
  return Array.from({ length: totalDays }, (_, index) => `${year}-${String(month).padStart(2, "0")}-${String(index + 1).padStart(2, "0")}`)
}

function formatShiftScheduleMonth(monthValue: string) {
  const [year, month] = monthValue.split("-").map(Number)
  if (!year || !month) return monthValue || "Bulan belum dipilih"
  return new Intl.DateTimeFormat("id-ID", { month: "long", year: "numeric" }).format(new Date(year, month - 1, 1))
}

function getShiftScheduleDayLabel(dateKey: string) {
  const parsedDate = getShiftScheduleMonthDate(dateKey)
  return parsedDate ? SHIFT_SCHEDULE_DAY_LABELS[parsedDate.getDay()] : "-"
}

function normalizeShiftScheduleDates(dates: string[]) {
  return Array.from(new Set(dates.filter((date) => /^\d{4}-\d{2}-\d{2}$/.test(date)))).sort()
}

function getShiftScheduleMonthRange(monthValue: string) {
  const dates = getShiftScheduleMonthDates(monthValue)
  return {
    startDate: dates[0] || `${getLocalDateKey().slice(0, 7)}-01`,
    endDate: dates[dates.length - 1] || getLocalDateKey(),
  }
}

const SHIFT_SCHEDULE_TONES = [
  { surface: "rgba(236, 253, 255, 0.94)", border: "rgba(34, 174, 202, 0.56)", text: "#075f72", dot: "#06b6d4" },
  { surface: "rgba(240, 253, 244, 0.96)", border: "rgba(34, 197, 94, 0.44)", text: "#166534", dot: "#22c55e" },
  { surface: "rgba(255, 251, 235, 0.96)", border: "rgba(245, 158, 11, 0.46)", text: "#92400e", dot: "#f59e0b" },
  { surface: "rgba(239, 246, 255, 0.96)", border: "rgba(59, 130, 246, 0.44)", text: "#1d4ed8", dot: "#3b82f6" },
  { surface: "rgba(254, 242, 242, 0.96)", border: "rgba(248, 113, 113, 0.46)", text: "#991b1b", dot: "#ef4444" },
  { surface: "rgba(245, 243, 255, 0.96)", border: "rgba(139, 92, 246, 0.42)", text: "#5b21b6", dot: "#8b5cf6" },
]

function getShiftScheduleToneStyle(shiftId: string, shifts: ShiftScheduleShiftOption[], mode: "default" | "override" = "override"): CSSProperties {
  const directIndex = shifts.findIndex((shift) => shift.id === shiftId)
  const fallbackIndex = shiftId.split("").reduce((total, character) => total + character.charCodeAt(0), 0)
  const tone = SHIFT_SCHEDULE_TONES[(directIndex >= 0 ? directIndex : fallbackIndex) % SHIFT_SCHEDULE_TONES.length]

  return {
    "--shift-surface": mode === "default" ? "rgba(255, 255, 255, 0.78)" : tone.surface,
    "--shift-border": mode === "default" ? "rgba(148, 163, 184, 0.18)" : tone.border,
    "--shift-text": mode === "default" ? "#64748b" : tone.text,
    "--shift-dot": mode === "default" ? "rgba(148, 163, 184, 0.62)" : tone.dot,
  } as CSSProperties
}

function createShiftScheduleFormValues(row: ShiftScheduleRow | null, fallbackDate = getLocalDateKey(), fallbackEmployeeId = ""): ShiftScheduleFormValues {
  const scheduleDate = row?.scheduleDate || fallbackDate
  return {
    mode: "single",
    employeeId: row?.employeeId || fallbackEmployeeId,
    scheduleDate,
    scheduleMonth: getShiftScheduleMonthValue(scheduleDate),
    selectedDates: [scheduleDate],
    dateShiftIds: row?.scheduleShiftId ? { [scheduleDate]: row.scheduleShiftId } : {},
    shiftId: row?.scheduleShiftId || row?.defaultShiftId || "",
    workLocationId: row?.scheduleWorkLocationId || row?.defaultWorkLocationId || "",
    notes: row?.scheduleNotes || "",
  }
}

function getShiftScheduleSearchText(row: ShiftScheduleRow) {
  return [
    row.employeeCode,
    row.fullName,
    row.divisionName,
    row.defaultShiftName,
    row.scheduleShiftName,
    row.defaultWorkLocationName,
    row.scheduleWorkLocationName,
    row.scheduleNotes,
    getShiftScheduleSourceLabel(row),
  ].join(" ").toLowerCase()
}

async function loadShiftScheduleData(targetDate = getLocalDateKey()): Promise<ShiftScheduleData> {
  const [employeeResult, divisionResult, locationResult, shiftResult, scheduleResult] = await Promise.all([
    supabase
      .from("employees")
      .select("id, employee_code, full_name, photo_path, division_id, work_location_id, shift_id, status, deleted_at")
      .is("deleted_at", null)
      .order("employee_code", { ascending: true }),
    supabase.from("divisions").select("id, code, name, is_active, sort_order").order("sort_order", { ascending: true }).order("code", { ascending: true }),
    supabase.from("work_locations").select("id, code, name, is_active, sort_order").order("sort_order", { ascending: true }).order("code", { ascending: true }),
    supabase.from("shifts").select("id, code, name, start_time, end_time, late_tolerance_minutes, early_leave_tolerance_minutes, is_active, sort_order").order("sort_order", { ascending: true }).order("code", { ascending: true }),
    supabase
      .from("employee_shift_schedules")
      .select("id, employee_id, schedule_date, shift_id, work_location_id, status, notes, updated_at")
      .eq("schedule_date", targetDate)
      .order("updated_at", { ascending: false }),
  ])
  const scheduleSchemaReady = !(scheduleResult.error && isMissingShiftScheduleSchema(scheduleResult.error))
  const error = employeeResult.error || divisionResult.error || locationResult.error || shiftResult.error || (scheduleSchemaReady ? scheduleResult.error : null)

  if (error) throw error

  const divisions = (divisionResult.data || []).map((row) => ({
    id: String(row.id),
    code: String(row.code || ""),
    name: String(row.name || ""),
    isActive: row.is_active !== false,
  }))
  const locations = (locationResult.data || []).map((row) => ({
    id: String(row.id),
    code: String(row.code || ""),
    name: String(row.name || ""),
    isActive: row.is_active !== false,
  }))
  const shifts = ((shiftResult.data || []) as Array<Record<string, unknown>>).map(createShiftScheduleOption)
  const divisionMap = new Map(divisions.map((item) => [item.id, item]))
  const locationMap = new Map(locations.map((item) => [item.id, item]))
  const shiftMap = new Map(shifts.map((item) => [item.id, item]))
  const scheduleMap = new Map(((scheduleSchemaReady ? scheduleResult.data || [] : []) as Array<Record<string, unknown>>).map((row) => [String(row.employee_id || ""), row]))

  const rows = ((employeeResult.data || []) as Array<Record<string, unknown>>)
    .filter((employee) => String(employee.status || "active") === "active")
    .map((employee) => {
      const employeeId = String(employee.id || "")
      const defaultShiftId = String(employee.shift_id || "")
      const defaultLocationId = String(employee.work_location_id || "")
      const dailySchedule = scheduleMap.get(employeeId)
      const scheduleStatus = mapShiftScheduleStatus(dailySchedule?.status)
      const hasActiveSchedule = Boolean(dailySchedule?.id && scheduleStatus === "active")
      const defaultShift = shiftMap.get(defaultShiftId)
      const scheduleShiftId = hasActiveSchedule ? String(dailySchedule?.shift_id || "") : ""
      const scheduleShift = hasActiveSchedule ? shiftMap.get(scheduleShiftId) : undefined
      const scheduleLocationId = hasActiveSchedule ? String(dailySchedule?.work_location_id || "") : ""
      const scheduleLocation = hasActiveSchedule ? locationMap.get(scheduleLocationId) : undefined
      const resolvedShift = scheduleShift || defaultShift
      const resolvedLocation = scheduleLocation || locationMap.get(defaultLocationId)

      return {
        id: `${employeeId}:${targetDate}`,
        employeeId,
        employeeCode: String(employee.employee_code || ""),
        fullName: String(employee.full_name || ""),
        photoUrl: getEmployeePhotoPublicUrl(String(employee.photo_path || "")),
        divisionId: String(employee.division_id || ""),
        divisionName: divisionMap.get(String(employee.division_id || ""))?.name || "Belum pilih divisi",
        defaultShiftId,
        defaultShiftName: defaultShift?.name || "Belum pilih shift",
        defaultShiftStartTime: defaultShift?.startTime || "",
        defaultShiftEndTime: defaultShift?.endTime || "",
        defaultWorkLocationId: defaultLocationId,
        defaultWorkLocationName: locationMap.get(defaultLocationId)?.name || "Belum pilih lokasi",
        scheduleId: String(dailySchedule?.id || ""),
        scheduleDate: String(dailySchedule?.schedule_date || targetDate),
        scheduleShiftId,
        scheduleShiftName: scheduleShift?.name || "",
        scheduleShiftStartTime: scheduleShift?.startTime || "",
        scheduleShiftEndTime: scheduleShift?.endTime || "",
        scheduleWorkLocationId: scheduleLocationId,
        scheduleWorkLocationName: scheduleLocation?.name || "",
        scheduleStatus,
        scheduleNotes: String(dailySchedule?.notes || ""),
        source: hasActiveSchedule ? "daily_schedule" : resolvedShift ? "employee_default" : "no_shift",
        updatedAt: String(dailySchedule?.updated_at || ""),
        resolvedShift,
        resolvedLocation,
      } as ShiftScheduleRow
    })

  return { rows, divisions, locations, shifts, schemaReady: scheduleSchemaReady }
}

async function loadEmployeeShiftSchedulesForMonth(employeeId: string, monthValue: string): Promise<ShiftScheduleMonthEntry[]> {
  if (!employeeId || !/^\d{4}-\d{2}$/.test(monthValue)) return []

  const { startDate, endDate } = getShiftScheduleMonthRange(monthValue)
  const { data, error } = await supabase
    .from("employee_shift_schedules")
    .select("id, employee_id, schedule_date, shift_id, work_location_id, status, notes")
    .eq("employee_id", employeeId)
    .gte("schedule_date", startDate)
    .lte("schedule_date", endDate)
    .order("schedule_date", { ascending: true })

  if (error) {
    if (isMissingShiftScheduleSchema(error)) return []
    throw error
  }

  return ((data || []) as Array<Record<string, unknown>>)
    .filter((row) => mapShiftScheduleStatus(row.status) === "active")
    .map((row) => ({
      id: String(row.id || ""),
      employeeId: String(row.employee_id || ""),
      scheduleDate: String(row.schedule_date || ""),
      shiftId: String(row.shift_id || ""),
      workLocationId: String(row.work_location_id || ""),
      status: mapShiftScheduleStatus(row.status),
      notes: String(row.notes || ""),
    }))
}

function validateShiftScheduleForm(values: ShiftScheduleFormValues) {
  const errors: string[] = []

  if (!values.employeeId) errors.push("Karyawan wajib dipilih.")
  if (values.mode === "month") {
    if (!/^\d{4}-\d{2}$/.test(values.scheduleMonth)) errors.push("Bulan jadwal wajib valid.")
    const targetDates = normalizeShiftScheduleDates(values.selectedDates.filter((date) => date.startsWith(`${values.scheduleMonth}-`)))
    if (targetDates.length === 0) errors.push("Minimal satu tanggal harus dicentang.")
    if (targetDates.some((date) => !values.dateShiftIds[date] && !values.shiftId)) errors.push("Semua tanggal terpilih wajib punya shift.")
  } else if (!values.scheduleDate || !/^\d{4}-\d{2}-\d{2}$/.test(values.scheduleDate)) {
    errors.push("Tanggal jadwal wajib valid.")
  } else if (!values.shiftId) errors.push("Shift wajib dipilih.")

  return errors
}

async function saveEmployeeShiftSchedule(values: ShiftScheduleFormValues, editingRow?: ShiftScheduleRow | null) {
  const errors = validateShiftScheduleForm(values)
  if (errors.length) throw new Error(errors[0])

  const targetDates = values.mode === "month"
    ? normalizeShiftScheduleDates(values.selectedDates.filter((date) => date.startsWith(`${values.scheduleMonth}-`)))
    : [values.scheduleDate]
  const payload = targetDates.map((scheduleDate) => ({
    employee_id: values.employeeId,
    schedule_date: scheduleDate,
    shift_id: values.mode === "month" ? values.dateShiftIds[scheduleDate] || values.shiftId : values.shiftId,
    work_location_id: values.workLocationId || null,
    status: "active",
    notes: values.notes.trim() || null,
  }))
  const { error } = await supabase
    .from("employee_shift_schedules")
    .upsert(payload, { onConflict: "employee_id,schedule_date" })

  if (error) throw error

  await Promise.all(targetDates.map((scheduleDate) => (
    supabase.rpc("refresh_attendance_daily_summary", {
      target_employee_id: values.employeeId,
      target_attendance_date: scheduleDate,
    }).then(({ error: refreshError }) => {
      if (refreshError) throw refreshError
    })
  )))
  await refreshEmployeePayrollCyclesSilently(values.employeeId)
  await writeAuditLog(editingRow?.scheduleId ? "Update employee shift schedule" : "Create employee shift schedule", "employee_shift_schedules", editingRow?.scheduleId || values.employeeId, {
    employee_id: values.employeeId,
    schedule_date: values.mode === "single" ? targetDates[0] : null,
    schedule_dates: values.mode === "month" ? targetDates : null,
    schedule_mode: values.mode,
    shift_id: values.mode === "single" ? values.shiftId : null,
    shift_ids: values.mode === "month" ? Array.from(new Set(targetDates.map((date) => values.dateShiftIds[date] || values.shiftId))).filter(Boolean) : null,
    work_location_id: values.workLocationId || null,
  }).catch(() => {})

  return targetDates
}

async function cancelEmployeeShiftSchedule(row: ShiftScheduleRow) {
  if (!row.scheduleId) return

  const { error } = await supabase
    .from("employee_shift_schedules")
    .update({ status: "cancelled" })
    .eq("id", row.scheduleId)

  if (error) throw error

  await supabase.rpc("refresh_attendance_daily_summary", {
    target_employee_id: row.employeeId,
    target_attendance_date: row.scheduleDate,
  }).then(({ error: refreshError }) => {
    if (refreshError) throw refreshError
  })
  await refreshEmployeePayrollCyclesSilently(row.employeeId)
  await writeAuditLog("Cancel employee shift schedule", "employee_shift_schedules", row.scheduleId, {
    employee_id: row.employeeId,
    schedule_date: row.scheduleDate,
  }).catch(() => {})
}

function createEmployeePayload(values: EmployeeFormValues, photoPath = values.photoPath) {
  const usesAttendanceCycle = values.payrollMethod === "attendance_cycle"
  const payload: Record<string, unknown> = {
    employee_code: values.employeeCode.trim().toUpperCase(),
    full_name: values.fullName.trim(),
    photo_path: photoPath || null,
    nik: values.nik.trim() || null,
    phone: values.phone.trim() || null,
    email: values.email.trim().toLowerCase() || null,
    division_id: values.divisionId || null,
    position_id: values.positionId || null,
    work_location_id: values.workLocationId || null,
    shift_id: values.shiftId || null,
    salary_type: values.salaryType,
    daily_salary: Number(values.dailySalary || 0),
    monthly_salary: Number(values.monthlySalary || 0),
    payroll_method: values.payrollMethod,
    prorate_enabled: values.prorateEnabled,
    join_date: values.joinDate || null,
    payroll_cycle_days: usesAttendanceCycle ? Number(values.payrollCycleDays || 0) : 0,
    status: values.status,
    notes: values.notes.trim() || null,
  }

  if (values.payrollOpeningSchemaReady) {
    payload.payroll_cycle_opening_date = usesAttendanceCycle ? values.payrollCycleOpeningDate || null : null
  }

  if (values.employmentSchemaReady) {
    payload.employment_type_id = values.employmentTypeId || null
    payload.payroll_eligible = values.payrollEligible
    payload.employee_pay_policy = values.payrollEligible ? values.employeePayPolicy : "not_counted"
    payload.allowance_amount = Number(values.allowanceAmount || 0)
    payload.attendance_required = values.attendanceRequired
  }

  if (values.kioskSchemaReady) {
    payload.qr_token = values.qrToken.trim().toUpperCase() || null
    payload.rfid_uid = values.rfidUid.trim() || null
    payload.attendance_policy_id = values.attendancePolicyId || null
    payload.kiosk_access_enabled = values.kioskAccessEnabled
  }

  return payload
}

function validateEmployeeForm(values: EmployeeFormValues) {
  const errors: string[] = []
  const dailySalary = Number(values.dailySalary)
  const monthlySalary = Number(values.monthlySalary)
  const payrollCycleDays = Number(values.payrollCycleDays)
  const emailValid = !values.email.trim() || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())
  const photoFileValid = !values.photoFile || employeePhotoMimeTypes.includes(values.photoFile.type)
  const photoSizeValid = !values.photoFile || values.photoFile.size <= maxEmployeePhotoSize

  if (!values.fullName.trim()) errors.push("Nama karyawan wajib diisi.")
  if (!values.employeeCode.trim()) errors.push("Kode karyawan wajib tersedia otomatis.")
  if (!values.divisionId) errors.push("Divisi wajib dipilih dari Master Data.")
  if (!values.positionId) errors.push("Jabatan wajib dipilih dari Master Data.")
  if (!values.workLocationId) errors.push("Lokasi kerja wajib dipilih dari Master Data.")
  if (!values.shiftId) errors.push("Shift wajib dipilih dari Master Data.")
  if (!values.salaryType) errors.push("Tipe gaji wajib dipilih.")
  if (!values.payrollMethod) errors.push("Metode payroll wajib dipilih.")
  if (values.salaryType === "daily" && (!Number.isFinite(dailySalary) || dailySalary < 0)) errors.push("Gaji harian wajib angka 0 atau lebih.")
  if (values.salaryType === "daily" && Number.isFinite(dailySalary) && dailySalary > maxEmployeeDailySalary) errors.push(`Gaji harian maksimal ${formatCurrency(maxEmployeeDailySalary)}.`)
  if (values.salaryType === "monthly" && (!Number.isFinite(monthlySalary) || monthlySalary < 0)) errors.push("Gaji bulanan wajib angka 0 atau lebih.")
  if (values.salaryType === "monthly" && Number.isFinite(monthlySalary) && monthlySalary > maxEmployeeMonthlySalary) errors.push(`Gaji bulanan maksimal ${formatCurrency(maxEmployeeMonthlySalary)}.`)
  if (values.employeePayPolicy === "allowance" && values.payrollEligible) {
    const allowanceAmount = Number(values.allowanceAmount)
    if (!Number.isFinite(allowanceAmount) || allowanceAmount <= 0) errors.push("Nominal uang saku wajib lebih dari 0.")
  }
  if (values.payrollMethod === "attendance_cycle") {
    if (!Number.isFinite(payrollCycleDays) || payrollCycleDays < 0 || payrollCycleDays > 26) errors.push("Saldo awal cycle harus 0 sampai 26 hari.")
    if (values.payrollOpeningSchemaReady && payrollCycleDays > 0 && !values.payrollCycleOpeningDate) errors.push("Tanggal awal cycle wajib diisi saat saldo awal lebih dari 0.")
  }
  if (!emailValid) errors.push("Email karyawan belum valid.")
  if (!photoFileValid) errors.push("Foto wajib JPG, PNG, atau WEBP.")
  if (!photoSizeValid) errors.push("Ukuran foto maksimal 2MB.")
  if (values.kioskSchemaReady && values.kioskAccessEnabled && !values.qrToken.trim() && !values.rfidUid.trim()) {
    errors.push("Akses kiosk aktif wajib punya token barcode/QR atau UID RFID.")
  }

  return errors
}

async function removeEmployeePhoto(path: string) {
  if (!path) return
  const { error } = await supabase.storage.from(employeePhotoBucket).remove([path])

  if (error) throw error
}

async function uploadEmployeePhoto(values: EmployeeFormValues) {
  if (!values.photoFile) return values.photoPath

  const path = buildEmployeePhotoPath(values.employeeCode)
  const { error } = await supabase.storage.from(employeePhotoBucket).upload(path, values.photoFile, {
    cacheControl: "3600",
    contentType: values.photoFile.type,
    upsert: true,
  })

  if (error) throw error
  return path
}

async function refreshEmployeePayrollCyclesSilently(employeeId: string) {
  try {
    await supabase.rpc("refresh_employee_payroll_cycles", { target_employee_id: employeeId })
  } catch {
    // Payroll preview can be refreshed again from the payroll/attendance module.
  }
}

async function saveEmployee(values: EmployeeFormValues, editingRow?: EmployeeDirectoryRow | null) {
  const originalPhotoPath = editingRow?.photoPath || values.photoPath
  const nextPhotoPath = values.photoFile
    ? buildEmployeePhotoPath(values.employeeCode)
    : values.removePhoto
      ? ""
      : values.photoPath
  const payload = createEmployeePayload(values, nextPhotoPath)

  if (!editingRow) {
    let uploadedPath = ""

    try {
      if (values.photoFile) {
        uploadedPath = await uploadEmployeePhoto(values)
      }

      const { data, error } = await supabase.from("employees").insert(payload).select("id").single()

      if (error) throw error
      if (data?.id) await refreshEmployeePayrollCyclesSilently(String(data.id))
    } catch (error) {
      if (uploadedPath) await removeEmployeePhoto(uploadedPath).catch(() => {})
      throw error
    }

    return
  }

  const { error } = await supabase.from("employees").update(payload).eq("id", editingRow.id)

  if (error) throw error

  try {
    if (values.photoFile) await uploadEmployeePhoto(values)
    if (values.removePhoto && originalPhotoPath) await removeEmployeePhoto(originalPhotoPath)
    if (values.photoFile && originalPhotoPath && originalPhotoPath !== nextPhotoPath) await removeEmployeePhoto(originalPhotoPath)
  } catch (photoError) {
    await supabase.from("employees").update({ photo_path: originalPhotoPath || null }).eq("id", editingRow.id)
    throw photoError
  }

  await refreshEmployeePayrollCyclesSilently(editingRow.id)
}

async function updateEmployeeStatus(row: EmployeeDirectoryRow, status: EmployeeStatus) {
  const { error } = await supabase.from("employees").update({ status }).eq("id", row.id)

  if (error) throw error
}

async function deleteEmployee(row: EmployeeDirectoryRow) {
  const { error } = await supabase
    .from("employees")
    .update({
      status: "inactive",
      deleted_at: new Date().toISOString(),
      photo_path: null,
    })
    .eq("id", row.id)

  if (error) throw error

  if (row.photoPath) await removeEmployeePhoto(row.photoPath).catch(() => {})
}

async function restoreEmployee(row: EmployeeDirectoryRow) {
  const { error } = await supabase
    .from("employees")
    .update({
      status: "active",
      deleted_at: null,
    })
    .eq("id", row.id)

  if (error) throw error
}

