function getLocalDateKey(date = new Date()) {
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, "0")
  const day = String(date.getDate()).padStart(2, "0")

  return `${year}-${month}-${day}`
}

function shiftDateKey(value: string, offsetDays: number) {
  const base = value ? new Date(`${value}T00:00:00+07:00`) : new Date()
  base.setDate(base.getDate() + offsetDays)
  return getLocalDateKey(base)
}

function getMonthDateRange(value: string) {
  const base = value ? new Date(`${value}T00:00:00+07:00`) : new Date()
  const start = new Date(base.getFullYear(), base.getMonth(), 1)
  const end = new Date(base.getFullYear(), base.getMonth() + 1, 0)

  return { start: getLocalDateKey(start), end: getLocalDateKey(end) }
}

function getAttendanceDateRange(selectedDate: string, mode: AttendanceDateMode) {
  if (mode === "last7" || mode === "week") return { start: shiftDateKey(selectedDate, -6), end: selectedDate }
  if (mode === "last30") return { start: shiftDateKey(selectedDate, -29), end: selectedDate }
  if (mode === "month") return getMonthDateRange(selectedDate)
  if (mode === "year") return { start: `${selectedDate.slice(0, 4)}-01-01`, end: selectedDate }
  if (mode === "all") return { start: "", end: selectedDate }
  return { start: selectedDate, end: selectedDate }
}

function getAttendanceModeLoadRange(selectedDate: string, mode: AttendanceDateMode) {
  const range = getAttendanceDateRange(selectedDate, mode)
  return normalizeAttendanceLoadRange(selectedDate, {
    startDate: range.start || shiftDateKey(range.end || selectedDate, -369),
    endDate: range.end || selectedDate,
  })
}

function normalizeAttendanceLoadRange(targetDate: string, options: AttendanceLoadOptions = {}) {
  const fallbackDate = targetDate || getLocalDateKey()
  const start = options.startDate || fallbackDate
  const end = options.endDate || fallbackDate

  return start <= end
    ? { startDate: start, endDate: end }
    : { startDate: end, endDate: start }
}

function getAttendanceDateKeys(startDate: string, endDate: string, maxDays = 370) {
  const dates: string[] = []
  let currentDate = startDate

  while (currentDate <= endDate && dates.length < maxDays) {
    dates.push(currentDate)
    currentDate = shiftDateKey(currentDate, 1)
  }

  return dates
}

const ATTENDANCE_BACKEND_REFRESH_MAX_DAYS = 31

function getAttendanceBackendRefreshRange(startDate: string, endDate: string) {
  const probeDates = getAttendanceDateKeys(startDate, endDate, ATTENDANCE_BACKEND_REFRESH_MAX_DAYS + 1)
  const lastProbeDate = probeDates[probeDates.length - 1] || startDate

  if (probeDates.length <= ATTENDANCE_BACKEND_REFRESH_MAX_DAYS && lastProbeDate === endDate) {
    return { startDate, endDate }
  }

  return {
    startDate: shiftDateKey(endDate, -(ATTENDANCE_BACKEND_REFRESH_MAX_DAYS - 1)),
    endDate,
  }
}

type SupabaseRangeQuery<T> = {
  range: (from: number, to: number) => PromiseLike<{ data: T[] | null; error: unknown }>
}

async function fetchSupabaseRangeRows<T>(
  buildQuery: () => SupabaseRangeQuery<T>,
  pageSize = 1000,
  maxRows = 100000,
) {
  const rows: T[] = []

  for (let offset = 0; offset < maxRows; offset += pageSize) {
    const { data, error } = await buildQuery().range(offset, offset + pageSize - 1)

    if (error) throw error
    const pageRows = data || []
    rows.push(...pageRows)

    if (pageRows.length < pageSize) return rows
  }

  throw new Error("Data rekap terlalu besar untuk dimuat sekaligus. Persempit range tanggal lalu coba lagi.")
}

async function fetchPayrollPaymentRows() {
  try {
    const rows = await fetchSupabaseRangeRows<Record<string, unknown>>(() => supabase
      .from("payroll_payments")
      .select("id, payment_no, payroll_cycle_id, employee_id, employee_code, employee_name, cycle_number, period_started_at, period_closed_at, gross_amount, overtime_amount, net_amount, paid_amount, payment_method, payment_reference, paid_at, paid_by_name, status, notes")
      .order("paid_at", { ascending: false })
      .order("payment_no", { ascending: false }), 500, 20000)

    return { data: rows, error: null }
  } catch (error) {
    return { data: [], error }
  }
}

async function fetchOvertimePaymentRows() {
  try {
    const rows = await fetchSupabaseRangeRows<Record<string, unknown>>(() => supabase
      .from("overtime_payments")
      .select("id, payment_no, employee_id, employee_code, employee_name, period_started_at, period_closed_at, request_count, overtime_minutes, overtime_amount, paid_amount, payment_method, payment_reference, paid_at, paid_by_name, status, notes")
      .order("paid_at", { ascending: false })
      .order("payment_no", { ascending: false }), 500, 20000)

    return { data: rows, error: null }
  } catch (error) {
    return { data: [], error }
  }
}

const overtimeRequestBaseColumns = "id, employee_id, attendance_log_id, payroll_cycle_id, payroll_component_id, overtime_date, shift_start_time, shift_end_time, actual_check_out_at, overtime_minutes, approved_minutes, rate_amount, total_amount, day_type, overtime_basis, status, request_source, planned_start_at, planned_end_at, planned_minutes, request_reason, requested_at, matched_attendance, notes, created_at"
const overtimeRequestPaymentColumns = `${overtimeRequestBaseColumns}, overtime_payment_status, overtime_payment_policy, overtime_payment_id, overtime_paid_at, overtime_payment_note`
const overtimeRequestTimingColumns = `${overtimeRequestPaymentColumns}, actual_check_in_at, pre_shift_minutes, post_shift_minutes`

async function fetchOvertimeRequestRows(startDate: string, endDate: string, dateScoped = true) {
  const runQuery = (columns: string) => fetchSupabaseRangeRows<Record<string, unknown>>(() => {
    const query = supabase
      .from("overtime_requests")
      .select(columns)

    const scopedQuery = dateScoped
      ? query.gte("overtime_date", startDate).lte("overtime_date", endDate)
      : query

    return scopedQuery
      .order("overtime_date", { ascending: false })
      .order("created_at", { ascending: false }) as unknown as SupabaseRangeQuery<Record<string, unknown>>
  }, 500, 10000)

  try {
    const rows = await runQuery(overtimeRequestTimingColumns)
    return { data: rows, error: null }
  } catch (error) {
    if (!isMissingOvertimeTimingSchema(error) && !isMissingOvertimePaymentSchema(error)) return { data: [], error }

    try {
      const rows = await runQuery(overtimeRequestPaymentColumns)
      return { data: rows, error: null }
    } catch (paymentError) {
      if (!isMissingOvertimePaymentSchema(paymentError)) return { data: [], error: paymentError }

      try {
        const rows = await runQuery(overtimeRequestBaseColumns)
        return { data: rows, error: null }
      } catch (legacyError) {
        return { data: [], error: legacyError }
      }
    }
  }
}

function formatAttendanceTime(value?: string | null) {
  if (!value) return "Belum absen"
  return new Intl.DateTimeFormat("id-ID", {
    hour: "2-digit",
    minute: "2-digit",
    timeZone: "Asia/Jakarta",
  }).format(new Date(value))
}

function formatAttendanceTimeInput(value?: string | null, fallback = "17:00") {
  if (!value) return fallback
  const date = new Date(value)
  if (!Number.isFinite(date.getTime())) return fallback

  return new Intl.DateTimeFormat("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
    timeZone: "Asia/Jakarta",
  }).format(date)
}

function addMinutesToIsoTimeInput(value: string, minutes: number, fallback = "17:00") {
  if (!value) return fallback
  const date = new Date(value)
  if (!Number.isFinite(date.getTime())) return fallback
  date.setMinutes(date.getMinutes() + minutes)
  return formatAttendanceTimeInput(date.toISOString(), fallback)
}

function formatWorkDate(value?: string | null) {
  if (!value) return "-"
  return new Intl.DateTimeFormat("id-ID", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: "Asia/Jakarta",
  }).format(new Date(`${value}T00:00:00+07:00`))
}

function formatAttendanceRangeLabel(selectedDate: string, mode: AttendanceDateMode) {
  const range = getAttendanceDateRange(selectedDate, mode)
  if (!range.start) return `Sampai ${formatWorkDate(range.end)}`
  if (range.start !== range.end) return `${formatWorkDate(range.start)} - ${formatWorkDate(range.end)}`
  return formatWorkDate(range.end)
}

function getAttendanceRangeMetricLabel(mode: AttendanceDateMode) {
  if (mode === "last7" || mode === "week") return "7 Hari"
  if (mode === "last30" || mode === "month") return "30 Hari"
  if (mode === "year") return "Tahun"
  if (mode === "all") return "Semua waktu"
  return "Tanggal"
}

function getAttendanceRecapTitle(selectedDate: string, mode: AttendanceDateMode) {
  return `Rekap ${formatAttendanceRangeLabel(selectedDate, mode)}`
}

function formatMinutesDuration(minutes: number) {
  const safeMinutes = Math.max(0, Math.round(minutes))
  const hours = Math.floor(safeMinutes / 60)
  const restMinutes = safeMinutes % 60

  if (hours === 0) return `${restMinutes}m`
  if (restMinutes === 0) return `${hours}j`
  return `${hours}j ${restMinutes}m`
}

function parseShiftTimeMinutes(value?: string | null) {
  const match = String(value || "").match(/^(\d{1,2}):(\d{2})/)
  if (!match) return null
  const hour = Number(match[1])
  const minute = Number(match[2])
  if (!Number.isFinite(hour) || !Number.isFinite(minute) || hour < 0 || hour > 23 || minute < 0 || minute > 59) return null
  return hour * 60 + minute
}

function formatShiftClock(value?: string | null) {
  const minutes = parseShiftTimeMinutes(value)
  if (minutes === null) return "--:--"
  return `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`
}

function buildJakartaDateTimeIso(dateKey: string, totalMinutes: number) {
  const dayOffset = Math.floor(totalMinutes / 1440)
  const minuteOfDay = ((totalMinutes % 1440) + 1440) % 1440
  const date = shiftDateKey(dateKey, dayOffset)
  return `${date}T${String(Math.floor(minuteOfDay / 60)).padStart(2, "0")}:${String(minuteOfDay % 60).padStart(2, "0")}:00+07:00`
}

function getScheduledShiftWindow(attendanceDate: string, startTime?: string | null, endTime?: string | null) {
  const startMinutes = parseShiftTimeMinutes(startTime)
  const endMinutes = parseShiftTimeMinutes(endTime)
  if (!attendanceDate || startMinutes === null || endMinutes === null) return null

  const normalizedEndMinutes = endMinutes <= startMinutes ? endMinutes + 1440 : endMinutes
  return {
    startAt: buildJakartaDateTimeIso(attendanceDate, startMinutes),
    endAt: buildJakartaDateTimeIso(attendanceDate, normalizedEndMinutes),
    expectedMinutes: normalizedEndMinutes - startMinutes,
    isOvernight: normalizedEndMinutes >= 1440,
  }
}

function getAttendanceDurationMinutes(checkInAt?: string | null, checkOutAt?: string | null) {
  if (!checkInAt) return null
  const startMs = new Date(checkInAt).getTime()
  const endMs = checkOutAt ? new Date(checkOutAt).getTime() : Date.now()
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs < startMs) return null
  return Math.round((endMs - startMs) / 60000)
}

const OPEN_SHIFT_LIMIT_MINUTES = 16 * 60

function isPastAttendanceDate(attendanceDate?: string | null) {
  return Boolean(attendanceDate && attendanceDate < getLocalDateKey())
}

function isMissingCheckoutShift(checkInAt?: string | null, checkOutAt?: string | null, attendanceDate?: string | null) {
  if (!checkInAt || checkOutAt) return false
  const minutes = getAttendanceDurationMinutes(checkInAt, null)
  if (minutes === null) return false
  return isPastAttendanceDate(attendanceDate) || minutes > OPEN_SHIFT_LIMIT_MINUTES
}

function canCorrectMissingCheckout(row: AttendanceMonitorRow) {
  return Boolean(row.checkInId && !row.checkOutId)
}

function canCorrectAttendanceCheckIn(row: AttendanceMonitorRow) {
  return Boolean(row.employeeId && row.attendanceDate)
}

function formatAttendanceWorkDuration(checkInAt?: string | null, checkOutAt?: string | null, attendanceDate?: string | null) {
  const minutes = getAttendanceDurationMinutes(checkInAt, checkOutAt)
  if (minutes === null) return "Belum mulai"
  if (!checkOutAt && isMissingCheckoutShift(checkInAt, checkOutAt, attendanceDate)) return "Belum checkout"
  return checkOutAt ? formatMinutesDuration(minutes) : `Berjalan ${formatMinutesDuration(minutes)}`
}

function calculateAttendanceSettlement({
  attendanceDate,
  checkInAt,
  checkOutAt,
  shiftName,
  shiftStartTime,
  shiftEndTime,
  lateToleranceMinutes = 0,
  earlyLeaveToleranceMinutes = 0,
  attendanceStatus,
}: {
  attendanceDate: string
  checkInAt: string
  checkOutAt: string
  shiftName: string
  shiftStartTime: string
  shiftEndTime: string
  lateToleranceMinutes?: number
  earlyLeaveToleranceMinutes?: number
  attendanceStatus: AttendanceStatus
}) {
  const schedule = getScheduledShiftWindow(attendanceDate, shiftStartTime, shiftEndTime)
  const actualWorkMinutes = checkInAt && checkOutAt ? getAttendanceDurationMinutes(checkInAt, checkOutAt) : null
  const checkInMs = checkInAt ? new Date(checkInAt).getTime() : null
  const checkOutMs = checkOutAt ? new Date(checkOutAt).getTime() : null
  const scheduledStartMs = schedule ? new Date(schedule.startAt).getTime() : null
  const scheduledEndMs = schedule ? new Date(schedule.endAt).getTime() : null
  const rawLateMinutes = scheduledStartMs !== null && checkInMs !== null && Number.isFinite(checkInMs)
    ? Math.max(0, Math.floor((checkInMs - scheduledStartMs) / 60000))
    : 0
  const rawEarlyLeaveMinutes = scheduledEndMs !== null && checkOutMs !== null && Number.isFinite(checkOutMs)
    ? Math.max(0, Math.floor((scheduledEndMs - checkOutMs) / 60000))
    : 0
  const lateMinutes = Math.max(0, rawLateMinutes - Math.max(0, lateToleranceMinutes))
  const earlyLeaveMinutes = Math.max(0, rawEarlyLeaveMinutes - Math.max(0, earlyLeaveToleranceMinutes))
  const overtimeMinutes = scheduledEndMs !== null && checkOutMs !== null && Number.isFinite(checkOutMs)
    ? Math.max(0, Math.floor((checkOutMs - scheduledEndMs) / 60000))
    : 0
  const shortageMinutes = schedule && actualWorkMinutes !== null
    ? Math.max(0, schedule.expectedMinutes - actualWorkMinutes)
    : 0
  const lastActivityAt = [checkInAt, checkOutAt]
    .filter(Boolean)
    .sort((a, b) => new Date(b).getTime() - new Date(a).getTime())[0] || ""

  let settlementStatus: AttendanceSettlementStatus = "ready"
  if (attendanceStatus === "failed") settlementStatus = "failed"
  else if (!checkInAt) settlementStatus = "missing_checkin"
  else if (!checkOutAt) settlementStatus = isMissingCheckoutShift(checkInAt, checkOutAt, attendanceDate) ? "missing_checkout" : "running"
  else if (!schedule) settlementStatus = "no_shift"
  else if (attendanceStatus === "pending") settlementStatus = "review"
  else if (shortageMinutes > 0) settlementStatus = "short"

  const settlementTone: AttendanceSettlementTone =
    settlementStatus === "ready" ? "valid"
      : settlementStatus === "failed" ? "failed"
      : settlementStatus === "missing_checkin" || settlementStatus === "missing_checkout" ? "missing"
        : "pending"
  const settlementLabel =
    settlementStatus === "ready" ? "Sesuai shift"
      : settlementStatus === "running" ? "Sedang berjalan"
      : settlementStatus === "short" ? `Kurang ${formatMinutesDuration(shortageMinutes)}`
      : settlementStatus === "missing_checkout" ? "Belum checkout"
      : settlementStatus === "missing_checkin" ? "Belum masuk"
      : settlementStatus === "review" ? "Review HR"
      : settlementStatus === "failed" ? "Tidak valid"
        : "Shift belum lengkap"

  return {
    scheduledStartAt: schedule?.startAt || "",
    scheduledEndAt: schedule?.endAt || "",
    expectedWorkMinutes: schedule?.expectedMinutes ?? null,
    actualWorkMinutes,
    shiftLateToleranceMinutes: Math.max(0, lateToleranceMinutes),
    shiftEarlyLeaveToleranceMinutes: Math.max(0, earlyLeaveToleranceMinutes),
    lateMinutes,
    earlyLeaveMinutes,
    shortageMinutes,
    overtimeMinutes,
    lastActivityAt,
    settlementStatus,
    settlementLabel,
    settlementTone,
    shiftScheduleLabel: schedule ? `${formatShiftClock(shiftStartTime)} - ${formatShiftClock(shiftEndTime)}${schedule.isOvernight ? " +1" : ""}` : "Shift belum lengkap",
    shiftName: shiftName || "Belum pilih shift",
  }
}

function mapDailySummaryAttendanceStatus(value: unknown): AttendanceStatus {
  if (value === "valid" || value === "pending" || value === "failed" || value === "missing") return value
  return "missing"
}

function mapDailySummarySettlementStatus(value: unknown): AttendanceSettlementStatus {
  if (
    value === "ready"
    || value === "running"
    || value === "short"
    || value === "missing_checkout"
    || value === "missing_checkin"
    || value === "review"
    || value === "failed"
    || value === "no_shift"
    || value === "excused_paid"
    || value === "excused_unpaid"
    || value === "field_assignment"
    || value === "alpha"
    || value === "off_day"
  ) return value
  return "missing_checkin"
}

function getAttendanceSettlementTone(status: AttendanceSettlementStatus): AttendanceSettlementTone {
  if (status === "ready" || status === "excused_paid" || status === "field_assignment") return "valid"
  if (status === "failed" || status === "alpha") return "failed"
  if (status === "missing_checkin" || status === "missing_checkout" || status === "off_day") return "missing"
  return "pending"
}

function getAttendanceSettlementLabel(status: AttendanceSettlementStatus, shortageMinutes = 0) {
  if (status === "ready") return "Sesuai shift"
  if (status === "running") return "Sedang berjalan"
  if (status === "short") return `Kurang ${formatMinutesDuration(shortageMinutes)}`
  if (status === "missing_checkout") return "Belum checkout"
  if (status === "missing_checkin") return "Belum masuk"
  if (status === "review") return "Review HR"
  if (status === "failed") return "Tidak valid"
  if (status === "excused_paid") return "Izin dibayar"
  if (status === "excused_unpaid") return "Izin tidak dibayar"
  if (status === "field_assignment") return "Tugas luar"
  if (status === "alpha") return "Alpha"
  if (status === "off_day") return "Libur"
  return "Shift belum lengkap"
}

function compareAttendanceRowsByLatestActivity(a: AttendanceMonitorRow, b: AttendanceMonitorRow) {
  const aTime = a.lastActivityAt ? new Date(a.lastActivityAt).getTime() : 0
  const bTime = b.lastActivityAt ? new Date(b.lastActivityAt).getTime() : 0
  if (aTime !== bTime) return bTime - aTime
  const dateCompare = b.attendanceDate.localeCompare(a.attendanceDate)
  if (dateCompare !== 0) return dateCompare
  return a.employeeCode.localeCompare(b.employeeCode)
}

function compareAttendanceRowsByCycleProgress(a: AttendanceMonitorRow, b: AttendanceMonitorRow) {
  const cycleCompare = b.cycleDays - a.cycleDays
  if (cycleCompare !== 0) return cycleCompare
  return compareAttendanceRowsByLatestActivity(a, b)
}

function getAttendanceShiftScheduleLabel(row: AttendanceMonitorRow) {
  if (!row.scheduledStartAt || !row.scheduledEndAt) return "jadwal belum lengkap"
  const crossesDate = row.scheduledStartAt.slice(0, 10) !== row.scheduledEndAt.slice(0, 10)
  return `${formatAttendanceTime(row.scheduledStartAt)} - ${formatAttendanceTime(row.scheduledEndAt)}${crossesDate ? " +1" : ""}`
}

function getAttendanceSettlementDescription(row: AttendanceMonitorRow) {
  const expected = row.expectedWorkMinutes === null ? "wajib belum terbaca" : `wajib ${formatMinutesDuration(row.expectedWorkMinutes)}`
  const actual = row.actualWorkMinutes === null ? "aktual belum final" : `aktual ${formatMinutesDuration(row.actualWorkMinutes)}`

  if (row.leaveRequestId) {
    const reason = row.leaveReason ? ` - ${row.leaveReason}` : ""
    return `${getLeaveRequestTypeLabel(row.leaveRequestType)} ${getLeaveRequestStatusLabel(row.leaveRequestStatus)}. ${getLeavePayPolicyLabel(row.leavePayPolicy)}${reason}.`
  }
  if (row.settlementStatus === "ready") return `${actual} sudah memenuhi ${expected}.`
  if (row.settlementStatus === "running") return `Shift sedang berjalan; ${actual} dan akan final setelah check-out.`
  if (row.settlementStatus === "short") return `${actual}, kurang ${formatMinutesDuration(row.shortageMinutes)} dari ${expected}.`
  if (row.settlementStatus === "missing_checkout") return "Check-in sudah ada, tetapi check-out belum tercatat."
  if (row.settlementStatus === "missing_checkin") return "Belum ada check-in untuk tanggal ini."
  if (row.settlementStatus === "review") return "Data absensi validasi GPS/face masih perlu review HR."
  if (row.settlementStatus === "failed") return "Data absensi ditandai tidak valid dan perlu pengecekan."
  return "Shift karyawan belum punya jam mulai dan jam selesai lengkap."
}

function getAttendanceSearchText(row: AttendanceMonitorRow) {
  const operationalKeywords = [
    row.lateMinutes > 0 ? "telat terlambat late" : "",
    row.earlyLeaveMinutes > 0 ? "pulang cepat early leave" : "",
    row.shortageMinutes > 0 ? "kurang jam short shortage" : "",
    row.overtimeMinutes > 0 ? "lembur overtime lewat shift" : "",
    row.checkInId && !row.checkOutId ? "belum checkout belum pulang" : "",
    !row.checkInId ? "belum masuk belum absen" : "",
  ]

  return [
    row.employeeCode,
    row.fullName,
    row.divisionName,
    row.workLocationName,
    row.shiftName,
    getAttendanceShiftScheduleLabel(row),
    row.attendanceStatus,
    row.settlementStatus,
    row.settlementLabel,
    row.payrollStatus,
    row.gpsStatus,
    row.faceStatus,
    row.checkInStatus,
    row.checkOutStatus,
    row.checkInSource,
    row.checkInMedia,
    row.checkOutSource,
    row.checkOutMedia,
    row.checkInDeviceId,
    row.checkOutDeviceId,
    row.checkInBiofingerEventId,
    row.checkOutBiofingerEventId,
    row.notes,
    row.overtimeRequestStatus,
    row.overtimeRequestSource,
    row.overtimeRequestReason,
    row.overtimeBasis,
    row.leaveRequestStatus,
    row.leaveRequestType,
    row.leavePayPolicy,
    row.leaveReason,
    getLeaveRequestTypeLabel(row.leaveRequestType),
    getLeaveRequestStatusLabel(row.leaveRequestStatus),
    getLeavePayPolicyLabel(row.leavePayPolicy),
    getAttendanceOvertimeInlineLabel(row),
    ...operationalKeywords,
  ].join(" ").toLowerCase()
}

function matchesAttendanceRecapStatus(row: AttendanceMonitorRow, statusFilter: string) {
  if (statusFilter === "all") return true
  if (statusFilter === "ready") return row.settlementStatus === "ready"
  if (statusFilter === "short") return row.settlementStatus === "short" || row.shortageMinutes > 0
  if (statusFilter === "late") return row.lateMinutes > 0
  if (statusFilter === "early_leave") return row.earlyLeaveMinutes > 0
  if (statusFilter === "overtime") return row.overtimeMinutes > 0
  if (statusFilter === "overtime_request") return Boolean(row.overtimeRequestId)
  if (statusFilter === "overtime_pending") return row.overtimeRequestStatus === "pending"
  if (statusFilter === "overtime_planned") return row.overtimeRequestStatus === "draft" && row.overtimeRequestSource === "planned"
  if (statusFilter === "overtime_approved") return row.overtimeRequestStatus === "approved"
  if (statusFilter === "leave_request") return Boolean(row.leaveRequestId)
  if (statusFilter === "excused_paid") return row.settlementStatus === "excused_paid"
  if (statusFilter === "excused_unpaid") return row.settlementStatus === "excused_unpaid"
  if (statusFilter === "field_assignment") return row.settlementStatus === "field_assignment"
  if (statusFilter === "alpha") return row.settlementStatus === "alpha"
  if (statusFilter === "off_day") return row.settlementStatus === "off_day"
  if (statusFilter === "running") return row.settlementStatus === "running"
  if (statusFilter === "missing_checkout") return row.settlementStatus === "missing_checkout"
  if (statusFilter === "missing_checkin" || statusFilter === "missing") return row.settlementStatus === "missing_checkin" || (!row.leaveRequestId && row.attendanceStatus === "missing")
  if (statusFilter === "review" || statusFilter === "pending") return row.settlementStatus === "review" || row.attendanceStatus === "pending"
  if (statusFilter === "failed") return row.settlementStatus === "failed" || row.attendanceStatus === "failed"
  if (statusFilter === "no_shift") return row.settlementStatus === "no_shift"
  return row.attendanceStatus === statusFilter
    || row.payrollStatus === statusFilter
    || row.gpsStatus === statusFilter
    || row.faceStatus === statusFilter
    || row.settlementStatus === statusFilter
}

function mapPayrollCycleStatus(status: unknown): PayrollStatus {
  if (status === "ready" || status === "locked" || status === "paid" || status === "void") return status
  return "active"
}

function mapPayrollPaymentMethod(value: unknown): PayrollPaymentMethod {
  if (value === "cash" || value === "ewallet" || value === "other") return value
  return "bank_transfer"
}

function mapPayrollPaymentStatus(value: unknown): PayrollPaymentStatus {
  if (value === "void" || value === "reversed") return value
  return "paid"
}

function mapPayrollPaymentRecord(row: Record<string, unknown>): PayrollPaymentRow {
  return {
    id: String(row.id || ""),
    paymentNo: String(row.payment_no || ""),
    payrollCycleId: String(row.payroll_cycle_id || ""),
    employeeId: String(row.employee_id || ""),
    employeeCode: String(row.employee_code || ""),
    employeeName: String(row.employee_name || "Karyawan"),
    cycleNumber: Number(row.cycle_number || 0),
    periodStartedAt: String(row.period_started_at || ""),
    periodClosedAt: String(row.period_closed_at || ""),
    grossAmount: Number(row.gross_amount || 0),
    overtimeAmount: Number(row.overtime_amount || 0),
    netAmount: Number(row.net_amount || 0),
    paidAmount: Number(row.paid_amount || 0),
    paymentMethod: mapPayrollPaymentMethod(row.payment_method),
    paymentReference: String(row.payment_reference || ""),
    paidAt: String(row.paid_at || ""),
    paidByName: String(row.paid_by_name || ""),
    status: mapPayrollPaymentStatus(row.status),
    notes: String(row.notes || ""),
  }
}

function mapOvertimePaymentRecord(row: Record<string, unknown>): OvertimePaymentRow {
  return {
    id: String(row.id || ""),
    paymentNo: String(row.payment_no || ""),
    employeeId: String(row.employee_id || ""),
    employeeCode: String(row.employee_code || ""),
    employeeName: String(row.employee_name || "Karyawan"),
    periodStartedAt: String(row.period_started_at || ""),
    periodClosedAt: String(row.period_closed_at || ""),
    requestCount: Number(row.request_count || 0),
    overtimeMinutes: Number(row.overtime_minutes || 0),
    overtimeAmount: Number(row.overtime_amount || 0),
    paidAmount: Number(row.paid_amount || 0),
    paymentMethod: mapPayrollPaymentMethod(row.payment_method),
    paymentReference: String(row.payment_reference || ""),
    paidAt: String(row.paid_at || ""),
    paidByName: String(row.paid_by_name || ""),
    status: mapPayrollPaymentStatus(row.status),
    notes: String(row.notes || ""),
  }
}

function mapOvertimePaymentStatus(value: unknown): OvertimePaymentStatus {
  if (value === "paid" || value === "void") return value
  return "unpaid"
}

function mapOvertimePaymentPolicy(value: unknown): OvertimePaymentPolicy {
  return value === "salary_cycle" ? "salary_cycle" : "separate"
}

function getAttendanceMonitorStatus(row?: Record<string, unknown>): AttendanceStatus {
  if (!row) return "missing"
  if (row.status === "valid") return "valid"
  if (row.status === "rejected" || row.face_status === "failed") return "failed"
  return "pending"
}

function getDailyAttendanceMonitorStatus(checkIn?: Record<string, unknown>, checkOut?: Record<string, unknown>): AttendanceStatus {
  if (!checkIn) return "missing"
  if (checkIn.status === "rejected" || checkOut?.status === "rejected" || checkIn.face_status === "failed" || checkOut?.face_status === "failed") return "failed"
  if (checkIn.status === "review" || checkOut?.status === "review" || checkIn.gps_status === "out_of_radius" || checkOut?.gps_status === "out_of_radius" || checkIn.face_status === "review" || checkOut?.face_status === "review") return "pending"
  if (!checkOut) return "pending"
  return "valid"
}

function getAttendanceLogTimeMs(row?: Record<string, unknown>) {
  const timeMs = new Date(String(row?.event_at || "")).getTime()
  return Number.isFinite(timeMs) ? timeMs : 0
}

function pickEarliestAttendanceLog(current: Record<string, unknown> | undefined, next: Record<string, unknown>) {
  if (!current) return next
  return getAttendanceLogTimeMs(next) < getAttendanceLogTimeMs(current) ? next : current
}

function pickLatestAttendanceLog(current: Record<string, unknown> | undefined, next: Record<string, unknown>) {
  if (!current) return next
  return getAttendanceLogTimeMs(next) > getAttendanceLogTimeMs(current) ? next : current
}

function getAttendanceReviewIssue(row: Record<string, unknown>) {
  if (row.status === "rejected") return "Ditolak HR"
  if (row.gps_status === "out_of_radius") return "Di luar radius"
  if (row.gps_status === "missing") return "GPS kosong"
  if (row.face_status === "failed") return "Face failed"
  if (row.face_status === "review") return "Face review"
  if (row.status === "review") return "Review manual"
  return "Valid"
}

function mapOvertimeStatus(value: unknown): OvertimeStatus {
  if (value === "approved" || value === "rejected" || value === "draft") return value
  return "pending"
}

function mapOvertimeRequestSource(value: unknown): OvertimeRequestSource {
  if (value === "planned" || value === "manual") return value
  return "auto"
}

function mapOvertimeBasis(value: unknown): OvertimeCalculationBasis {
  return value === "full_duration" ? "full_duration" : "extra_after_shift"
}

function mapLeaveRequestType(value: unknown): LeaveRequestType {
  if (value === "sick" || value === "leave" || value === "field_assignment" || value === "alpha" || value === "off") return value
  return "permit"
}

function mapLeaveRequestStatus(value: unknown): LeaveRequestStatus {
  if (value === "approved" || value === "rejected" || value === "cancelled") return value
  return "pending"
}

function mapLeavePayPolicy(value: unknown): LeavePayPolicy {
  if (value === "paid" || value === "not_counted") return value
  return "unpaid"
}

function getLeaveRequestTypeLabel(type?: LeaveRequestType | "") {
  if (type === "sick") return "Sakit"
  if (type === "leave") return "Cuti"
  if (type === "field_assignment") return "Tugas luar"
  if (type === "alpha") return "Alpha"
  if (type === "off") return "Libur"
  return "Izin"
}

function getLeaveRequestStatusLabel(status?: LeaveRequestStatus | "") {
  if (status === "approved") return "Disetujui"
  if (status === "rejected") return "Ditolak"
  if (status === "cancelled") return "Dibatalkan"
  return "Pending"
}

function getLeavePayPolicyLabel(policy?: LeavePayPolicy | "") {
  if (policy === "paid") return "Dibayar"
  if (policy === "not_counted") return "Tidak dihitung"
  return "Tidak dibayar"
}

function getLeaveRequestStatusTone(status?: LeaveRequestStatus | ""): AttendanceSettlementTone {
  if (status === "approved") return "valid"
  if (status === "rejected") return "failed"
  if (status === "cancelled") return "missing"
  return "pending"
}

function getDefaultLeavePayPolicy(type: LeaveRequestType): LeavePayPolicy {
  if (type === "sick" || type === "leave" || type === "field_assignment") return "paid"
  if (type === "off") return "not_counted"
  return "unpaid"
}

function getLeaveRequestDateLabel(row: LeaveRequestRow) {
  if (!row.startDate) return "-"
  if (!row.endDate || row.startDate === row.endDate) return formatWorkDate(row.startDate)
  return `${formatWorkDate(row.startDate)} - ${formatWorkDate(row.endDate)}`
}

async function loadOperationsFoundationData(targetDate = getLocalDateKey(), options: AttendanceLoadOptions = {}): Promise<OperationsFoundationData> {
  const selectedDate = targetDate || getLocalDateKey()
  const { startDate, endDate } = normalizeAttendanceLoadRange(selectedDate, options)
  const attendanceLogEndDate = shiftDateKey(endDate, 1)
  const loadScope: AttendanceLoadScope = options.scope || "full"
  const recapOnly = loadScope === "attendance-recap"
  const emptyResult = Promise.resolve({ data: [], error: null })

  if (options.refreshBackend) {
    const backendRange = getAttendanceBackendRefreshRange(startDate, endDate)
    const summaryRefresh = await supabase.rpc("refresh_attendance_daily_summaries", {
      target_start_date: backendRange.startDate,
      target_end_date: backendRange.endDate,
    })
    if (summaryRefresh.error) throw summaryRefresh.error
  }

  if (options.refreshOvertime || options.refreshPayroll) {
    const overtimeDetect = await supabase.rpc("detect_all_overtime_requests")
    if (overtimeDetect.error) throw overtimeDetect.error
  }

  if (options.refreshPayroll) {
    const payrollRefresh = await supabase.rpc("refresh_all_employee_payroll_cycles")
    if (payrollRefresh.error) throw payrollRefresh.error
  }

  const attendanceLogColumns = "id, employee_id, work_location_id, attendance_date, event_type, event_at, latitude, longitude, distance_m, radius_m, gps_status, face_status, face_score, face_snapshot_path, status, workday_counted, source, attendance_media, attendance_device_id, biofinger_event_id, notes"
  const [employeeResult, divisionResult, locationResult, shiftResult, attendanceRows, dailySummaryRows, reviewAttendanceResult, payrollRows, overtimeResult, payrollComponentResult, appUserResult, faceProfileResult, leaveResult, payrollPaymentResult, overtimePaymentResult] = await Promise.all([
    supabase
      .from("employees")
      .select("id, employee_code, full_name, photo_path, division_id, work_location_id, shift_id, salary_type, daily_salary, monthly_salary, payroll_cycle_days, payroll_eligible, employee_pay_policy, allowance_amount, employment_type_id, status, deleted_at")
      .is("deleted_at", null)
      .order("employee_code", { ascending: true }),
    supabase.from("divisions").select("id, name"),
    supabase.from("work_locations").select("id, code, name, address, latitude, longitude, radius_m, is_active").order("sort_order", { ascending: true }).order("code", { ascending: true }),
    supabase.from("shifts").select("id, code, name, start_time, end_time, late_tolerance_minutes, early_leave_tolerance_minutes, is_active, sort_order").order("sort_order", { ascending: true }).order("code", { ascending: true }),
    fetchSupabaseRangeRows<Record<string, unknown>>(() => supabase
      .from("attendance_logs")
      .select(attendanceLogColumns)
      .gte("attendance_date", startDate)
      .lte("attendance_date", attendanceLogEndDate)
      .order("event_at", { ascending: false })
      .order("id", { ascending: true })),
    fetchSupabaseRangeRows<Record<string, unknown>>(() => supabase
      .from("attendance_daily_summaries")
      .select("employee_id, attendance_date, work_location_id, shift_id, shift_name, shift_start_time, shift_end_time, shift_late_tolerance_minutes, shift_early_leave_tolerance_minutes, scheduled_start_at, scheduled_end_at, check_in_log_id, check_out_log_id, actual_check_in_at, actual_check_out_at, expected_work_minutes, actual_work_minutes, late_minutes, early_leave_minutes, shortage_minutes, overtime_minutes, attendance_status, settlement_status, workday_counted, leave_request_id, leave_type, leave_status, leave_pay_policy, leave_reason, payroll_cycle_id, notes, calculated_at")
      .gte("attendance_date", startDate)
      .lte("attendance_date", endDate)
      .order("attendance_date", { ascending: false })
      .order("employee_id", { ascending: true })),
    recapOnly ? emptyResult : fetchSupabaseRangeRows<Record<string, unknown>>(() => supabase
      .from("attendance_logs")
      .select(attendanceLogColumns)
      .eq("status", "review")
      .gte("attendance_date", startDate)
      .lte("attendance_date", endDate)
      .order("event_at", { ascending: false })
      .order("id", { ascending: true }), 500, 10000).then((data) => ({ data, error: null })),
    fetchSupabaseRangeRows<Record<string, unknown>>(() => supabase
      .from("payroll_cycles")
      .select("id, employee_id, cycle_number, period_started_at, period_closed_at, work_days_count, target_work_days, gross_amount, overtime_amount, net_amount, salary_type, status, ready_at, locked_at, paid_at")
      .order("cycle_number", { ascending: false })
      .order("employee_id", { ascending: true }), 1000, 50000),
    fetchOvertimeRequestRows(startDate, endDate, options.overtimeDateScoped !== false),
    supabase
      .from("payroll_components")
      .select("id, name, code, calculation_unit, rate_amount, day_type, overtime_basis, auto_detect_overtime"),
    recapOnly ? emptyResult : supabase
      .from("app_users")
      .select("id, user_code, full_name, status, employee_id, app_scope")
      .in("app_scope", ["field", "both"])
      .order("user_code", { ascending: true }),
    recapOnly ? emptyResult : supabase
      .from("employee_face_profiles")
      .select("employee_id, status, verification_required, face_score_threshold"),
    fetchSupabaseRangeRows<Record<string, unknown>>(() => supabase
      .from("leave_requests")
      .select("id, employee_id, request_type, start_date, end_date, pay_policy, status, reason, attachment_url, requested_by, reviewed_by, reviewed_at, review_notes, payroll_cycle_id, created_at, updated_at")
      .lte("start_date", endDate)
      .gte("end_date", startDate)
      .order("start_date", { ascending: false })
      .order("created_at", { ascending: false }), 500, 10000).then((data) => ({ data, error: null })),
    options.includePayrollPayments ? fetchPayrollPaymentRows() : emptyResult,
    options.includeOvertimePayments ? fetchOvertimePaymentRows() : emptyResult,
  ])
  const payrollPaymentError = payrollPaymentResult.error && !isMissingPayrollLedgerSchema(payrollPaymentResult.error) ? payrollPaymentResult.error : null
  const overtimePaymentError = overtimePaymentResult.error && !isMissingOvertimePaymentSchema(overtimePaymentResult.error) ? overtimePaymentResult.error : null
  const error = employeeResult.error || divisionResult.error || locationResult.error || shiftResult.error || reviewAttendanceResult.error || overtimeResult.error || payrollComponentResult.error || appUserResult.error || faceProfileResult.error || leaveResult.error || payrollPaymentError || overtimePaymentError

  if (error) throw error

  const divisionMap = new Map((divisionResult.data || []).map((row) => [String(row.id), String(row.name || "")]))
  const locationRows = (locationResult.data || []) as Array<Record<string, unknown>>
  const locationMap = new Map(locationRows.map((row) => [String(row.id), row]))
  const shiftMap = new Map(((shiftResult.data || []) as Array<Record<string, unknown>>).map((row) => [String(row.id), row]))
  const appUserRows = (appUserResult.data || []) as Array<Record<string, unknown>>
  const appUserByEmployee = new Map<string, Record<string, unknown>>()
  appUserRows.forEach((row) => {
    const employeeId = String(row.employee_id || "")
    if (!employeeId || appUserByEmployee.has(employeeId)) return
    appUserByEmployee.set(employeeId, row)
  })
  const faceProfileMap = new Map(((faceProfileResult.data || []) as Array<Record<string, unknown>>).map((row) => [String(row.employee_id || ""), row]))
  const reviewSourceLogs = (reviewAttendanceResult.data || []) as Array<Record<string, unknown>>
  const logsById = new Map<string, Record<string, unknown>>()
  const logs = [
    ...attendanceRows,
    ...reviewSourceLogs,
  ].filter((row) => {
    const id = String(row.id || "")
    if (!id || logsById.has(id)) return false
    logsById.set(id, row)
    return true
  })
  const dailySummaries = dailySummaryRows
  const summaryByEmployeeDate = new Map<string, Record<string, unknown>>()
  dailySummaries.forEach((row) => {
    const employeeId = String(row.employee_id || "")
    const attendanceDate = String(row.attendance_date || "")
    if (employeeId && attendanceDate) summaryByEmployeeDate.set(`${employeeId}:${attendanceDate}`, row)
  })
  const overtimeRows = (overtimeResult.data || []) as Array<Record<string, unknown>>
  const payrollPayments = (payrollPaymentResult.error && isMissingPayrollLedgerSchema(payrollPaymentResult.error))
    ? []
    : ((payrollPaymentResult.data || []) as Array<Record<string, unknown>>).map(mapPayrollPaymentRecord)
  const overtimePayments = (overtimePaymentResult.error && isMissingOvertimePaymentSchema(overtimePaymentResult.error))
    ? []
    : ((overtimePaymentResult.data || []) as Array<Record<string, unknown>>).map(mapOvertimePaymentRecord)
  const payrollComponentMap = new Map(((payrollComponentResult.data || []) as Array<Record<string, unknown>>).map((row) => [String(row.id), row]))
  const overtimeByEmployeeDate = new Map<string, Record<string, unknown>>()
  overtimeRows.forEach((row) => {
    const employeeId = String(row.employee_id || "")
    const overtimeDate = String(row.overtime_date || "")
    if (employeeId && overtimeDate) overtimeByEmployeeDate.set(`${employeeId}:${overtimeDate}`, row)
  })
  const payrollByEmployee = new Map<string, Record<string, unknown>>()
  const payrollById = new Map((payrollRows || []).map((row) => [String(row.id || ""), row]))

  payrollRows.forEach((row) => {
    const employeeId = String(row.employee_id || "")
    if (employeeId && !payrollByEmployee.has(employeeId)) payrollByEmployee.set(employeeId, row)
  })

  const selectedLogsByEmployee = new Map<string, { checkIn?: Record<string, unknown>; checkOut?: Record<string, unknown> }>()
  const logsByEmployeeDate = new Map<string, { checkIn?: Record<string, unknown>; checkOut?: Record<string, unknown> }>()
  logs.forEach((row) => {
    const employeeId = String(row.employee_id || "")
    if (!employeeId) return

    const attendanceDate = String(row.attendance_date || "")
    if (attendanceDate) {
      const key = `${employeeId}:${attendanceDate}`
      const dateEntry = logsByEmployeeDate.get(key) || {}
      if (row.event_type === "check_in") dateEntry.checkIn = pickEarliestAttendanceLog(dateEntry.checkIn, row)
      if (row.event_type === "check_out") dateEntry.checkOut = pickLatestAttendanceLog(dateEntry.checkOut, row)
      logsByEmployeeDate.set(key, dateEntry)
    }

    if (row.attendance_date !== selectedDate) return

    const entry = selectedLogsByEmployee.get(employeeId) || {}
    if (row.event_type === "check_in") entry.checkIn = pickEarliestAttendanceLog(entry.checkIn, row)
    if (row.event_type === "check_out") entry.checkOut = pickLatestAttendanceLog(entry.checkOut, row)
    selectedLogsByEmployee.set(employeeId, entry)
  })

  const buildAttendanceMonitorRow = (
    employee: Record<string, unknown>,
    dateKey: string,
    selectedAttendance?: { checkIn?: Record<string, unknown>; checkOut?: Record<string, unknown> },
    summary?: Record<string, unknown>,
  ): AttendanceMonitorRow => {
    const employeeId = String(employee.id)
    const overtimeRequest = overtimeByEmployeeDate.get(`${employeeId}:${dateKey}`)
    const overtimeComponent = payrollComponentMap.get(String(overtimeRequest?.payroll_component_id || ""))
    const attendance = (summary?.check_in_log_id ? logsById.get(String(summary.check_in_log_id)) : undefined) || selectedAttendance?.checkIn
    const checkOut = (summary?.check_out_log_id ? logsById.get(String(summary.check_out_log_id)) : undefined) || selectedAttendance?.checkOut
    const location = locationMap.get(String(summary?.work_location_id || employee.work_location_id || ""))
    const shift = shiftMap.get(String(summary?.shift_id || employee.shift_id || ""))
    const summaryPayrollId = String(summary?.payroll_cycle_id || "")
    const payroll = (summaryPayrollId ? payrollById.get(summaryPayrollId) : undefined) || payrollByEmployee.get(employeeId)
    const cycleDays = Number(payroll?.work_days_count ?? employee.payroll_cycle_days ?? 0)
    const targetDays = Number(payroll?.target_work_days ?? 26)
    const payrollPeriodClosedAt = String(payroll?.period_closed_at || "")
    const payrollClosingSummary = payrollPeriodClosedAt ? summaryByEmployeeDate.get(`${employeeId}:${payrollPeriodClosedAt}`) : undefined
    const payrollNeedsCheckout = Boolean(
      payroll
      && mapPayrollCycleStatus(payroll.status) === "ready"
      && cycleDays >= targetDays
      && payrollClosingSummary?.check_in_log_id
      && !payrollClosingSummary?.check_out_log_id
      && mapDailySummarySettlementStatus(payrollClosingSummary.settlement_status) === "missing_checkout",
    )
    const salaryType = mapEmployeeSalaryType(payroll?.salary_type || employee.salary_type)
    const basePayrollAmount = Number(payroll?.gross_amount || 0)
    const overtimeAmount = Number(payroll?.overtime_amount || 0)
    const payrollAmount = Number(payroll?.net_amount || 0) || basePayrollAmount + overtimeAmount
    const payrollEligible = employee.payroll_eligible !== false
    const employeePayPolicy = mapEmployeePayPolicy(employee.employee_pay_policy)
    const attendanceStatus = summary
      ? mapDailySummaryAttendanceStatus(summary.attendance_status)
      : getDailyAttendanceMonitorStatus(attendance, checkOut)
    const shiftId = String(summary?.shift_id || employee.shift_id || "")
    const shiftName = String(summary?.shift_name || shift?.name || "Belum pilih shift")
    const shiftStartTime = String(summary?.shift_start_time || shift?.start_time || "")
    const shiftEndTime = String(summary?.shift_end_time || shift?.end_time || "")
    const shiftLateToleranceMinutes = Number(summary?.shift_late_tolerance_minutes ?? shift?.late_tolerance_minutes ?? 0)
    const shiftEarlyLeaveToleranceMinutes = Number(summary?.shift_early_leave_tolerance_minutes ?? shift?.early_leave_tolerance_minutes ?? 0)
    const checkInAt = String(summary?.actual_check_in_at || attendance?.event_at || "")
    const checkOutAt = String(summary?.actual_check_out_at || checkOut?.event_at || "")
    const fallbackSettlement = calculateAttendanceSettlement({
      attendanceDate: attendance ? String(attendance.attendance_date || "") : dateKey,
      checkInAt,
      checkOutAt,
      shiftName,
      shiftStartTime,
      shiftEndTime,
      lateToleranceMinutes: shiftLateToleranceMinutes,
      earlyLeaveToleranceMinutes: shiftEarlyLeaveToleranceMinutes,
      attendanceStatus,
    })
    const settlementStatus = summary
      ? mapDailySummarySettlementStatus(summary.settlement_status)
      : fallbackSettlement.settlementStatus
    const expectedWorkMinutes = summary?.expected_work_minutes === null || summary?.expected_work_minutes === undefined
      ? fallbackSettlement.expectedWorkMinutes
      : Number(summary.expected_work_minutes)
    const actualWorkMinutes = summary?.actual_work_minutes === null || summary?.actual_work_minutes === undefined
      ? fallbackSettlement.actualWorkMinutes
      : Number(summary.actual_work_minutes)
    const lateMinutes = Number(summary?.late_minutes ?? fallbackSettlement.lateMinutes)
    const earlyLeaveMinutes = Number(summary?.early_leave_minutes ?? fallbackSettlement.earlyLeaveMinutes)
    const shortageMinutes = Number(summary?.shortage_minutes ?? fallbackSettlement.shortageMinutes)
    const overtimeMinutes = Number(summary?.overtime_minutes ?? fallbackSettlement.overtimeMinutes)
    const overtimeRequestStatus = overtimeRequest ? mapOvertimeStatus(overtimeRequest.status) : ""
    const overtimeRequestSource = overtimeRequest ? mapOvertimeRequestSource(overtimeRequest.request_source) : ""
    const overtimeBasis = overtimeRequest ? mapOvertimeBasis(overtimeRequest.overtime_basis || overtimeComponent?.overtime_basis) : ""
    const leaveRequestId = String(summary?.leave_request_id || "")
    const leaveRequestType = leaveRequestId ? mapLeaveRequestType(summary?.leave_type) : ""
    const leaveRequestStatus = leaveRequestId ? mapLeaveRequestStatus(summary?.leave_status) : ""
    const leavePayPolicy = leaveRequestId ? mapLeavePayPolicy(summary?.leave_pay_policy) : ""
    const leaveReason = String(summary?.leave_reason || "")
    const workdayCounted = summary ? summary.workday_counted === true : attendance?.workday_counted === true
    const lastActivityAt = [checkOutAt, checkInAt, String(summary?.calculated_at || ""), fallbackSettlement.lastActivityAt]
      .filter(Boolean)
      .sort((a, b) => new Date(String(b)).getTime() - new Date(String(a)).getTime())[0] || ""
    const fallbackLogStatus = attendanceStatus === "failed" ? "rejected" : attendanceStatus === "valid" ? "valid" : "review"
    const checkInStatus = attendance
      ? (attendance.status === "valid" || attendance.status === "rejected" ? attendance.status : "review")
      : checkInAt ? fallbackLogStatus : "missing"
    const checkOutStatus = checkOut
      ? (checkOut.status === "valid" || checkOut.status === "rejected" ? checkOut.status : "review")
      : checkOutAt ? fallbackLogStatus : "missing"

    return {
      id: attendance ? String(attendance.id) : `missing-${employeeId}-${dateKey}`,
      employeeId,
      employeeCode: String(employee.employee_code || ""),
      fullName: String(employee.full_name || ""),
      employeePhotoPath: String(employee.photo_path || ""),
      employeePhotoUrl: getEmployeePhotoPublicUrl(String(employee.photo_path || "")),
      divisionName: divisionMap.get(String(employee.division_id || "")) || "Belum pilih divisi",
      workLocationName: String(location?.name || "Belum pilih lokasi"),
      shiftId,
      shiftName,
      shiftStartTime,
      shiftEndTime,
      shiftLateToleranceMinutes,
      shiftEarlyLeaveToleranceMinutes,
      attendanceDate: attendance ? String(attendance.attendance_date || "") : dateKey,
      eventAt: attendance ? String(attendance.event_at || "") : "",
      checkInId: attendance ? String(attendance.id || "") : "",
      checkInAt,
      checkInStatus,
      checkInGpsStatus: attendance ? (attendance.gps_status === "valid" || attendance.gps_status === "out_of_radius" ? attendance.gps_status : "missing") : "missing",
      checkInFaceStatus: attendance ? (attendance.face_status === "verified" || attendance.face_status === "failed" || attendance.face_status === "review" ? attendance.face_status : "not_required") : "not_required",
      checkInFaceScore: attendance?.face_score === null || attendance?.face_score === undefined ? null : Number(attendance.face_score),
      checkInDistanceM: attendance?.distance_m === null || attendance?.distance_m === undefined ? null : Number(attendance.distance_m),
      checkInSource: String(attendance?.source || ""),
      checkInMedia: String(attendance?.attendance_media || ""),
      checkInDeviceId: String(attendance?.attendance_device_id || ""),
      checkInBiofingerEventId: String(attendance?.biofinger_event_id || ""),
      checkInNotes: String(attendance?.notes || ""),
      checkOutId: checkOut ? String(checkOut.id || "") : "",
      checkOutAt,
      checkOutStatus,
      checkOutGpsStatus: checkOut ? (checkOut.gps_status === "valid" || checkOut.gps_status === "out_of_radius" ? checkOut.gps_status : "missing") : "missing",
      checkOutFaceStatus: checkOut ? (checkOut.face_status === "verified" || checkOut.face_status === "failed" || checkOut.face_status === "review" ? checkOut.face_status : "not_required") : "not_required",
      checkOutFaceScore: checkOut?.face_score === null || checkOut?.face_score === undefined ? null : Number(checkOut.face_score),
      checkOutDistanceM: checkOut?.distance_m === null || checkOut?.distance_m === undefined ? null : Number(checkOut.distance_m),
      checkOutSource: String(checkOut?.source || ""),
      checkOutMedia: String(checkOut?.attendance_media || ""),
      checkOutDeviceId: String(checkOut?.attendance_device_id || ""),
      checkOutBiofingerEventId: String(checkOut?.biofinger_event_id || ""),
      checkOutNotes: String(checkOut?.notes || ""),
      attendanceStatus,
      logStatus: checkInStatus,
      gpsStatus: attendance ? (attendance.gps_status === "valid" || attendance.gps_status === "out_of_radius" ? attendance.gps_status : "missing") : "missing",
      faceStatus: attendance ? (attendance.face_status === "verified" || attendance.face_status === "failed" || attendance.face_status === "review" ? attendance.face_status : "not_required") : "not_required",
      faceScore: attendance?.face_score === null || attendance?.face_score === undefined ? null : Number(attendance.face_score),
      distanceM: attendance?.distance_m === null || attendance?.distance_m === undefined ? null : Number(attendance.distance_m),
      radiusM: Number(attendance?.radius_m || location?.radius_m || 0) || null,
      cycleDays,
      targetDays,
      payrollCycleId: String(payroll?.id || summaryPayrollId || ""),
      payrollCycleNumber: Number(payroll?.cycle_number || 0),
      periodStartedAt: String(payroll?.period_started_at || ""),
      periodClosedAt: payrollPeriodClosedAt,
      payrollReadyAt: String(payroll?.ready_at || ""),
      payrollLockedAt: String(payroll?.locked_at || ""),
      payrollPaidAt: String(payroll?.paid_at || ""),
      payrollStatus: mapPayrollCycleStatus(payroll?.status),
      payrollNeedsCheckout,
      payrollCheckoutNote: payrollNeedsCheckout ? "Hari ke-26 baru check-in. Checkout belum tercatat." : "",
      payrollEligible,
      employeePayPolicy,
      employmentTypeName: "",
      payrollAmount,
      basePayrollAmount,
      overtimeAmount,
      salaryType,
      workDurationLabel: leaveRequestId && !checkInAt ? getLeaveRequestTypeLabel(leaveRequestType) : actualWorkMinutes !== null ? formatMinutesDuration(actualWorkMinutes) : checkInAt ? formatAttendanceWorkDuration(checkInAt, checkOutAt || null, dateKey) : "Belum mulai",
      scheduledStartAt: String(summary?.scheduled_start_at || fallbackSettlement.scheduledStartAt || ""),
      scheduledEndAt: String(summary?.scheduled_end_at || fallbackSettlement.scheduledEndAt || ""),
      expectedWorkMinutes,
      actualWorkMinutes,
      lateMinutes,
      earlyLeaveMinutes,
      shortageMinutes,
      overtimeMinutes,
      overtimeRequestId: String(overtimeRequest?.id || ""),
      overtimeRequestStatus,
      overtimeRequestSource,
      overtimeRequestReason: String(overtimeRequest?.request_reason || ""),
      overtimePlannedMinutes: Number(overtimeRequest?.planned_minutes || 0),
      overtimeApprovedMinutes: Number(overtimeRequest?.approved_minutes || 0),
      overtimePayableMinutes: Number(overtimeRequest?.overtime_minutes || 0),
      overtimeRateAmount: Number(overtimeRequest?.rate_amount || overtimeComponent?.rate_amount || 0),
      overtimeTotalAmount: Number(overtimeRequest?.total_amount || 0),
      overtimeBasis,
      workdayCounted,
      leaveRequestId,
      leaveRequestType,
      leaveRequestStatus,
      leavePayPolicy,
      leaveReason,
      lastActivityAt,
      settlementStatus,
      settlementLabel: getAttendanceSettlementLabel(settlementStatus, shortageMinutes),
      settlementTone: getAttendanceSettlementTone(settlementStatus),
      notes: String(summary?.notes || attendance?.notes || ""),
    }
  }

  const activeEmployees = ((employeeResult.data || []) as Array<Record<string, unknown>>).filter((employee) => employee.status !== "inactive")

  const rows: AttendanceMonitorRow[] = activeEmployees
    .map((employee) => {
      const employeeId = String(employee.id)
      return buildAttendanceMonitorRow(
        employee,
        selectedDate,
        selectedLogsByEmployee.get(employeeId),
        summaryByEmployeeDate.get(`${employeeId}:${selectedDate}`),
      )
    })

  const fieldReadiness: FieldReadinessRow[] = recapOnly ? [] : activeEmployees.map((employee) => {
    const employeeId = String(employee.id)
    const location = locationMap.get(String(employee.work_location_id || ""))
    const appUser = appUserByEmployee.get(employeeId)
    const appScope = mapAppScope(appUser?.app_scope)
    const userReady = Boolean(appUser && appUser.status === "active" && (appScope === "field" || appScope === "both"))
    const locationReady = isWorkLocationGpsReady(location)
    const faceReadiness = getFieldFaceReadiness(faceProfileMap.get(employeeId))
    const issue = getFieldReadinessIssue({
      userReady,
      hasUser: Boolean(appUser),
      locationReady,
      faceReady: faceReadiness.faceReady,
      faceStatus: faceReadiness.status,
    })

    return {
      id: employeeId,
      employeeId,
      employeeCode: String(employee.employee_code || ""),
      fullName: String(employee.full_name || ""),
      employeePhotoUrl: getEmployeePhotoPublicUrl(String(employee.photo_path || "")),
      divisionName: divisionMap.get(String(employee.division_id || "")) || "Belum pilih divisi",
      workLocationName: String(location?.name || "Belum pilih lokasi"),
      workLocationCode: String(location?.code || ""),
      locationReady,
      appUserId: String(appUser?.id || ""),
      appUserCode: String(appUser?.user_code || ""),
      appUserName: String(appUser?.full_name || ""),
      appUserStatus: String(appUser?.status || ""),
      appScope,
      userReady,
      faceStatus: faceReadiness.status,
      faceRequired: faceReadiness.faceRequired,
      faceReady: faceReadiness.faceReady,
      ready: userReady && locationReady && faceReadiness.faceReady,
      issueLabel: issue.issueLabel,
      issueTone: issue.issueTone,
    }
  })

  const activeEmployeeMap = new Map(activeEmployees.map((employee) => [String(employee.id), employee]))
  const leaveRequests: LeaveRequestRow[] = ((leaveResult.data || []) as Array<Record<string, unknown>>)
    .map((leave) => {
      const employee = activeEmployeeMap.get(String(leave.employee_id || ""))

      return {
        id: String(leave.id || ""),
        employeeId: String(leave.employee_id || ""),
        employeeCode: String(employee?.employee_code || ""),
        fullName: String(employee?.full_name || "Karyawan tidak ditemukan"),
        employeePhotoPath: String(employee?.photo_path || ""),
        employeePhotoUrl: getEmployeePhotoPublicUrl(String(employee?.photo_path || "")),
        divisionName: divisionMap.get(String(employee?.division_id || "")) || "Belum pilih divisi",
        startDate: String(leave.start_date || ""),
        endDate: String(leave.end_date || ""),
        requestType: mapLeaveRequestType(leave.request_type),
        payPolicy: mapLeavePayPolicy(leave.pay_policy),
        status: mapLeaveRequestStatus(leave.status),
        reason: String(leave.reason || ""),
        attachmentUrl: String(leave.attachment_url || ""),
        requestedBy: String(leave.requested_by || ""),
        reviewedBy: String(leave.reviewed_by || ""),
        reviewedAt: String(leave.reviewed_at || ""),
        reviewNotes: String(leave.review_notes || ""),
        payrollCycleId: String(leave.payroll_cycle_id || ""),
        createdAt: String(leave.created_at || ""),
        updatedAt: String(leave.updated_at || ""),
      }
    })
    .sort((a, b) => {
      const dateCompare = b.startDate.localeCompare(a.startDate)
      if (dateCompare !== 0) return dateCompare
      return new Date(b.createdAt || b.updatedAt).getTime() - new Date(a.createdAt || a.updatedAt).getTime()
    })
  const rangeDateKeys = getAttendanceDateKeys(startDate, endDate)
  const allRows = rangeDateKeys.flatMap((attendanceDate) => activeEmployees.map((employee) => {
    const employeeId = String(employee.id)
    return buildAttendanceMonitorRow(
      employee,
      attendanceDate,
      logsByEmployeeDate.get(`${employeeId}:${attendanceDate}`),
      summaryByEmployeeDate.get(`${employeeId}:${attendanceDate}`),
    )
  }))
  allRows.sort(compareAttendanceRowsByLatestActivity)

  const employeesById = activeEmployeeMap
  const reviewRows: AttendanceReviewRow[] = recapOnly ? [] : reviewSourceLogs
    .filter((log) => log.status === "review")
    .map((log) => {
      const employee = employeesById.get(String(log.employee_id || ""))
      const location = locationMap.get(String(log.work_location_id || employee?.work_location_id || ""))
      const pairedLogs = logsByEmployeeDate.get(`${String(log.employee_id || "")}:${String(log.attendance_date || "")}`)
      const checkInLog = log.event_type === "check_in" ? log : pairedLogs?.checkIn
      const checkOutLog = log.event_type === "check_out" ? log : pairedLogs?.checkOut

      return {
        id: String(log.id),
        employeeId: String(log.employee_id || ""),
        employeeCode: String(employee?.employee_code || ""),
        fullName: String(employee?.full_name || "Karyawan tidak ditemukan"),
        employeePhotoPath: String(employee?.photo_path || ""),
        employeePhotoUrl: getEmployeePhotoPublicUrl(String(employee?.photo_path || "")),
        divisionName: divisionMap.get(String(employee?.division_id || "")) || "Belum pilih divisi",
        workLocationName: String(location?.name || "Belum pilih lokasi"),
        attendanceDate: String(log.attendance_date || ""),
        eventType: log.event_type === "check_out" ? "check_out" : "check_in",
        eventAt: String(log.event_at || ""),
        latitude: log.latitude === null || log.latitude === undefined ? "" : String(log.latitude),
        longitude: log.longitude === null || log.longitude === undefined ? "" : String(log.longitude),
        status: log.status === "valid" || log.status === "rejected" ? log.status : "review",
        gpsStatus: log.gps_status === "valid" || log.gps_status === "out_of_radius" ? log.gps_status : "missing",
        faceStatus: log.face_status === "verified" || log.face_status === "failed" || log.face_status === "review" ? log.face_status : "not_required",
        faceScore: log.face_score === null || log.face_score === undefined ? null : Number(log.face_score),
        faceSnapshotPath: String(log.face_snapshot_path || ""),
        faceSnapshotUrl: getAttendanceFacePublicUrl(String(log.face_snapshot_path || "")),
        distanceM: log.distance_m === null || log.distance_m === undefined ? null : Number(log.distance_m),
        radiusM: Number(log.radius_m || location?.radius_m || 0) || null,
        workLocationLatitude: location?.latitude === null || location?.latitude === undefined ? "" : String(location?.latitude || ""),
        workLocationLongitude: location?.longitude === null || location?.longitude === undefined ? "" : String(location?.longitude || ""),
        source: String(log.source || ""),
        media: String(log.attendance_media || ""),
        attendanceDeviceId: String(log.attendance_device_id || ""),
        biofingerEventId: String(log.biofinger_event_id || ""),
        workdayCounted: log.workday_counted === true,
        workDurationLabel: checkInLog ? formatAttendanceWorkDuration(String(checkInLog.event_at || ""), checkOutLog ? String(checkOutLog.event_at || "") : null, String(log.attendance_date || "")) : "Belum mulai",
        pairedCheckInAt: String(checkInLog?.event_at || ""),
        pairedCheckInStatus: checkInLog?.status === "valid" || checkInLog?.status === "rejected" ? checkInLog.status : checkInLog ? "review" : "missing",
        pairedCheckOutAt: String(checkOutLog?.event_at || ""),
        pairedCheckOutStatus: checkOutLog?.status === "valid" || checkOutLog?.status === "rejected" ? checkOutLog.status : checkOutLog ? "review" : "missing",
        issueLabel: getAttendanceReviewIssue(log),
        notes: String(log.notes || ""),
      }
    })

  const overtimeReviewRows: OvertimeReviewRow[] = recapOnly ? [] : overtimeRows.map((overtime) => {
    const employee = employeesById.get(String(overtime.employee_id || ""))
    const component = payrollComponentMap.get(String(overtime.payroll_component_id || ""))
    const payrollCycle = payrollById.get(String(overtime.payroll_cycle_id || "")) || payrollByEmployee.get(String(overtime.employee_id || ""))
    const overtimeStatus = String(overtime.status || "pending") as OvertimeStatus
    const dayType = String(overtime.day_type || "weekday")
    const requestSource = String(overtime.request_source || "auto")
    const overtimeBasis = String(overtime.overtime_basis || component?.overtime_basis || "extra_after_shift")

    return {
      id: String(overtime.id),
      employeeId: String(overtime.employee_id || ""),
      employeeCode: String(employee?.employee_code || ""),
      fullName: String(employee?.full_name || "Karyawan tidak ditemukan"),
      employeePhotoPath: String(employee?.photo_path || ""),
      employeePhotoUrl: getEmployeePhotoPublicUrl(String(employee?.photo_path || "")),
      divisionName: divisionMap.get(String(employee?.division_id || "")) || "Belum pilih divisi",
      overtimeDate: String(overtime.overtime_date || ""),
      shiftStartTime: String(overtime.shift_start_time || "").slice(0, 5),
      shiftEndTime: String(overtime.shift_end_time || "").slice(0, 5),
      actualCheckInAt: String(overtime.actual_check_in_at || ""),
      actualCheckOutAt: String(overtime.actual_check_out_at || ""),
      preShiftMinutes: Number(overtime.pre_shift_minutes || 0),
      postShiftMinutes: Number(overtime.post_shift_minutes || 0),
      overtimeMinutes: Number(overtime.overtime_minutes || 0),
      approvedMinutes: Number(overtime.approved_minutes || 0),
      rateAmount: Number(overtime.rate_amount || component?.rate_amount || 0),
      totalAmount: Number(overtime.total_amount || 0),
      dayType: dayType === "sunday" || dayType === "holiday" ? dayType : "weekday",
      overtimeBasis: overtimeBasis === "full_duration" ? "full_duration" : "extra_after_shift",
      status: overtimeStatus === "approved" || overtimeStatus === "rejected" || overtimeStatus === "draft" ? overtimeStatus : "pending",
      requestSource: requestSource === "planned" || requestSource === "manual" ? requestSource : "auto",
      plannedStartAt: String(overtime.planned_start_at || ""),
      plannedEndAt: String(overtime.planned_end_at || ""),
      plannedMinutes: Number(overtime.planned_minutes || 0),
      requestReason: String(overtime.request_reason || ""),
      requestedAt: String(overtime.requested_at || overtime.created_at || ""),
      matchedAttendance: overtime.matched_attendance === true || Boolean(overtime.actual_check_out_at),
      payrollCycleId: String(overtime.payroll_cycle_id || payrollCycle?.id || ""),
      payrollCycleNumber: Number(payrollCycle?.cycle_number || 0),
      payrollStatus: mapPayrollCycleStatus(payrollCycle?.status),
      overtimePaymentStatus: mapOvertimePaymentStatus(overtime.overtime_payment_status),
      overtimePaymentPolicy: mapOvertimePaymentPolicy(overtime.overtime_payment_policy),
      overtimePaymentId: String(overtime.overtime_payment_id || ""),
      overtimePaidAt: String(overtime.overtime_paid_at || ""),
      overtimePaymentNote: String(overtime.overtime_payment_note || ""),
      componentName: String(component?.name || "Komponen lembur"),
      notes: String(overtime.notes || ""),
    }
  })

  const locations: FieldLocationSummary[] = locationRows.map((location) => {
    const locationId = String(location.id)
    const employeeCount = rows.filter((row) => row.workLocationName === String(location.name || "")).length
    const locationTodayLogs = logs.filter((log) => log.attendance_date === selectedDate && String(log.work_location_id || "") === locationId)

    return {
      id: locationId,
      code: String(location.code || ""),
      name: String(location.name || ""),
      address: String(location.address || ""),
      latitude: location.latitude === null || location.latitude === undefined ? "" : String(location.latitude),
      longitude: location.longitude === null || location.longitude === undefined ? "" : String(location.longitude),
      radiusM: Number(location.radius_m || 0),
      isReady: Boolean(location.latitude && location.longitude && location.radius_m && location.is_active !== false),
      employeeCount,
      validToday: locationTodayLogs.filter((log) => log.status === "valid").length,
      reviewToday: locationTodayLogs.filter((log) => log.status === "review" || log.gps_status === "out_of_radius").length,
    }
  })

  return { rows, allRows, locations, fieldReadiness, reviews: reviewRows, overtime: overtimeReviewRows, leaveRequests, payrollPayments, overtimePayments }
}

function getBrowserPosition(): Promise<GeolocationPosition> {
  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) {
      reject(new Error("Browser belum mendukung GPS."))
      return
    }

    navigator.geolocation.getCurrentPosition(resolve, reject, {
      enableHighAccuracy: true,
      timeout: 12000,
      maximumAge: 0,
    })
  })
}

function stopMediaStream(stream: MediaStream | null) {
  stream?.getTracks().forEach((track) => track.stop())
}

function captureVideoFrame(video: HTMLVideoElement, contentType = "image/jpeg") {
  const width = video.videoWidth || 720
  const height = video.videoHeight || 960
  const canvas = document.createElement("canvas")
  canvas.width = width
  canvas.height = height
  const context = canvas.getContext("2d")

  if (!context) throw new Error("Kamera belum bisa diproses browser.")
  context.drawImage(video, 0, 0, width, height)
  return canvas.toDataURL(contentType, 0.88)
}

const faceEmbeddingModel = "@vladmandic/face-api:tiny-face-detector+68tiny+recognition@1.7.15"
const faceEmbeddingModelPath = "/face-models"
let faceEmbeddingEnginePromise: Promise<any> | null = null

async function loadFaceEmbeddingEngine() {
  if (!faceEmbeddingEnginePromise) {
    faceEmbeddingEnginePromise = import("@vladmandic/face-api").then(async (faceapi) => {
      await Promise.all([
        faceapi.nets.tinyFaceDetector.loadFromUri(faceEmbeddingModelPath),
        faceapi.nets.faceLandmark68TinyNet.loadFromUri(faceEmbeddingModelPath),
        faceapi.nets.faceRecognitionNet.loadFromUri(faceEmbeddingModelPath),
      ])
      return faceapi
    })
  }

  return faceEmbeddingEnginePromise
}

function normalizeFaceEmbedding(value: ArrayLike<number>) {
  const vector = Array.from(value, (item) => Number(item))
  if (vector.length !== 128 || vector.some((item) => !Number.isFinite(item))) {
    throw new Error("Embedding wajah tidak valid.")
  }
  return vector.map((item) => Number(item.toFixed(8)))
}

function loadImageFromDataUrl(dataUrl: string) {
  return new Promise<HTMLImageElement>((resolve, reject) => {
    const image = new Image()
    image.onload = () => resolve(image)
    image.onerror = () => reject(new Error("Snapshot wajah belum bisa dibaca."))
    image.src = dataUrl
  })
}

async function extractFaceEmbeddingFromMedia(source: HTMLVideoElement | HTMLImageElement) {
  const faceapi = await loadFaceEmbeddingEngine()
  const options = new faceapi.TinyFaceDetectorOptions({ inputSize: 224, scoreThreshold: 0.45 })
  const result = await faceapi
    .detectSingleFace(source, options)
    .withFaceLandmarks(true)
    .withFaceDescriptor()

  if (!result?.descriptor) throw new Error("Wajah belum terbaca oleh embedding engine.")
  return normalizeFaceEmbedding(result.descriptor)
}

async function extractFaceEmbeddingFromDataUrl(dataUrl: string) {
  const image = await loadImageFromDataUrl(dataUrl)
  return extractFaceEmbeddingFromMedia(image)
}

async function extractEnrollmentFaceEmbeddings(snapshotsBase64: string[]) {
  const embeddings: number[][] = []

  for (const snapshot of snapshotsBase64.slice(0, 3)) {
    embeddings.push(await extractFaceEmbeddingFromDataUrl(snapshot))
  }

  return embeddings
}

function calculateFrameQualityScore(video: HTMLVideoElement) {
  const width = 96
  const height = 128
  const canvas = document.createElement("canvas")
  canvas.width = width
  canvas.height = height
  const context = canvas.getContext("2d", { willReadFrequently: true })

  if (!context) return 0

  context.drawImage(video, 0, 0, width, height)
  const pixels = context.getImageData(0, 0, width, height).data
  let luminanceTotal = 0
  let luminanceSquaredTotal = 0

  for (let index = 0; index < pixels.length; index += 4) {
    const luminance = pixels[index] * 0.2126 + pixels[index + 1] * 0.7152 + pixels[index + 2] * 0.0722
    luminanceTotal += luminance
    luminanceSquaredTotal += luminance * luminance
  }

  const pixelCount = width * height
  const mean = luminanceTotal / pixelCount
  const variance = Math.max(0, luminanceSquaredTotal / pixelCount - mean * mean)
  const brightnessScore = Math.max(0, 1 - Math.abs(mean - 132) / 132)
  const contrastScore = Math.min(1, Math.sqrt(variance) / 58)

  return Math.round((brightnessScore * 0.64 + contrastScore * 0.36) * 100)
}

type FaceBox = { x: number; y: number; width: number; height: number }

function readFaceBox(detection: unknown): FaceBox | null {
  const candidate = detection as {
    boundingBox?: Partial<FaceBox>
    box?: Partial<FaceBox>
    detection?: { box?: Partial<FaceBox> }
  }
  const box = candidate.boundingBox || candidate.box || candidate.detection?.box
  if (!box) return null

  const x = Number(box.x)
  const y = Number(box.y)
  const width = Number(box.width)
  const height = Number(box.height)

  if (![x, y, width, height].every(Number.isFinite) || width <= 0 || height <= 0) return null
  return { x, y, width, height }
}

async function detectFaceBoxes(video: HTMLVideoElement) {
  const FaceDetectorConstructor = (window as unknown as {
    FaceDetector?: new (options?: { fastMode?: boolean; maxDetectedFaces?: number }) => {
      detect: (source: HTMLVideoElement) => Promise<Array<{ boundingBox: DOMRectReadOnly | FaceBox }>>
    }
  }).FaceDetector

  if (FaceDetectorConstructor) {
    const detector = new FaceDetectorConstructor({ fastMode: true, maxDetectedFaces: 2 })
    const nativeFaces = await detector.detect(video)
    return nativeFaces.map(readFaceBox).filter((box): box is FaceBox => Boolean(box))
  }

  const faceapi = await loadFaceEmbeddingEngine()
  const options = new faceapi.TinyFaceDetectorOptions({ inputSize: 224, scoreThreshold: 0.42 })
  const modelFaces = await faceapi.detectAllFaces(video, options) as unknown[]
  return modelFaces.map(readFaceBox).filter((box): box is FaceBox => Boolean(box))
}

function analyzeFaceBox(
  face: FaceBox,
  video: HTMLVideoElement,
  qualityScore: number,
  options: {
    centerToleranceX: number
    centerToleranceY: number
    idealHeightRatio: number
    heightTolerance: number
    minHeightRatio: number
    maxHeightRatio: number
    maxWidthRatio?: number
    readyScore: number
    centerMessage: string
    readyMessage: string
    holdMessage: string
    closeMessage: string
    farMessage: string
    centerWeight: number
    sizeWeight: number
    qualityWeight: number
  },
) {
  const width = video.videoWidth
  const height = video.videoHeight
  const centerX = face.x + face.width / 2
  const centerY = face.y + face.height / 2
  const offsetX = Math.abs(centerX - width / 2) / width
  const offsetY = Math.abs(centerY - height / 2) / height
  const faceWidthRatio = face.width / width
  const faceHeightRatio = face.height / height
  const centerScore = Math.max(0, 1 - (offsetX / options.centerToleranceX + offsetY / options.centerToleranceY) / 2)
  const sizeScore = Math.max(0, 1 - Math.abs(faceHeightRatio - options.idealHeightRatio) / options.heightTolerance)
  const score = Math.round((centerScore * options.centerWeight + sizeScore * options.sizeWeight + (qualityScore / 100) * options.qualityWeight) * 100)

  if (faceHeightRatio < options.minHeightRatio) return { supported: true, ready: false, score, message: options.farMessage }
  if (faceHeightRatio > options.maxHeightRatio || (options.maxWidthRatio && faceWidthRatio > options.maxWidthRatio)) {
    return { supported: true, ready: false, score, message: options.closeMessage }
  }
  if (offsetX > options.centerToleranceX || offsetY > options.centerToleranceY) {
    return { supported: true, ready: false, score, message: options.centerMessage }
  }

  return {
    supported: true,
    ready: score >= options.readyScore,
    score,
    message: score >= options.readyScore ? options.readyMessage : options.holdMessage,
  }
}

async function analyzeFaceEnrollmentFrame(video: HTMLVideoElement | null) {
  if (!video || !video.videoWidth || !video.videoHeight) {
    return { supported: true, ready: false, score: 0, message: "Preview kamera belum siap." }
  }

  const qualityScore = calculateFrameQualityScore(video)
  const faces = await detectFaceBoxes(video)

  if (faces.length === 0) return { supported: true, ready: false, score: qualityScore, message: "Posisikan wajah di tengah oval." }
  if (faces.length > 1) return { supported: true, ready: false, score: 0, message: "Pastikan hanya satu wajah di kamera." }

  return analyzeFaceBox(faces[0], video, qualityScore, {
    centerToleranceX: 0.24,
    centerToleranceY: 0.28,
    idealHeightRatio: 0.6,
    heightTolerance: 0.42,
    minHeightRatio: 0.28,
    maxHeightRatio: 0.96,
    maxWidthRatio: 0.92,
    readyScore: 62,
    centerMessage: "Geser wajah ke tengah oval.",
    readyMessage: "Wajah terbaca. Tahan sebentar.",
    holdMessage: "Wajah hampir pas. Tahan posisi.",
    closeMessage: "Wajah terlalu dekat. Mundur sedikit.",
    farMessage: "Dekatkan wajah ke kamera.",
    centerWeight: 0.44,
    sizeWeight: 0.28,
    qualityWeight: 0.28,
  })
}

async function analyzeAttendanceFaceFrame(video: HTMLVideoElement | null) {
  if (!video || !video.videoWidth || !video.videoHeight) {
    return { supported: true, ready: false, score: 0, message: "Preview kamera belum siap." }
  }

  const qualityScore = calculateFrameQualityScore(video)
  const faces = await detectFaceBoxes(video)

  if (faces.length === 0) return { supported: true, ready: false, score: qualityScore, message: "Wajah belum terbaca." }
  if (faces.length > 1) return { supported: true, ready: false, score: qualityScore, message: "Pastikan hanya satu wajah di kamera." }

  return analyzeFaceBox(faces[0], video, qualityScore, {
    centerToleranceX: 0.22,
    centerToleranceY: 0.26,
    idealHeightRatio: 0.56,
    heightTolerance: 0.36,
    minHeightRatio: 0.3,
    maxHeightRatio: 0.92,
    readyScore: 76,
    centerMessage: "Geser wajah ke tengah frame.",
    readyMessage: "Wajah terbaca. Menyimpan snapshot...",
    holdMessage: "Tahan wajah tetap sejajar.",
    closeMessage: "Wajah terlalu dekat. Mundur sedikit.",
    farMessage: "Dekatkan wajah sedikit.",
    centerWeight: 0.48,
    sizeWeight: 0.32,
    qualityWeight: 0.2,
  })
}

async function startUserCamera(video: HTMLVideoElement | null) {
  if (!video) throw new Error("Preview kamera belum siap.")
  if (!navigator.mediaDevices?.getUserMedia) throw new Error("Browser belum mendukung kamera. Gunakan Chrome/Safari terbaru dengan HTTPS.")

  const stream = await navigator.mediaDevices.getUserMedia({
    video: {
      facingMode: "user",
      width: { ideal: 720 },
      height: { ideal: 960 },
    },
    audio: false,
  })
  video.srcObject = stream
  await video.play()

  return stream
}

